184	  }
185	  if (
186	    manifest.public.appAuthority !== manifest.controlPlane.issuer ||
187	    manifest.public.mcpResource !== manifest.controlPlane.oauthResource ||
188	    (options.production &&
189	      (manifest.public.appAuthority !== PRODUCTION_APP_AUTHORITY ||
190	        manifest.public.mcpResource !== PRODUCTION_MCP_RESOURCE))
191	  ) {
