 83	    },
 84	    async update(input) {
 85	      const result = await sql.query<DirectoryRow>(
 86	        `UPDATE permission_directory_records
 87	            SET value = $2, indexes = $3::jsonb, expires_at = $4,
 88	                updated_at = now()
 89	          WHERE key = $1
 90	          RETURNING key, value, indexes, expires_at`,
 91	        [
 92	          input.key,
 93	          input.value,
 94	          JSON.stringify(input.indexes ?? {}),
 95	          expiry(input.ttlSeconds),
 96	        ],
 97	      );
 98	      const row = result.rows[0];
 99	      if (!row) throw new Error("PERMISSION_DIRECTORY_RECORD_NOT_FOUND");
100	      return record(row);
101	    },
102	    async delete(key) {
103	      await sql.query("DELETE FROM permission_directory_records WHERE key = $1", [key]);
104	    },
105	    async query(input) {
106	      const limit = Math.min(Math.max(input.limit ?? 100, 1), 100);
107	      const after = input.cursor ? decodeURIComponent(input.cursor) : "";
108	      const result = await sql.query<DirectoryRow>(
109	        `SELECT key, value, indexes, expires_at
110	           FROM permission_directory_records
111	          WHERE key > $3
112	            AND (expires_at IS NULL OR expires_at > now())
113	            AND (
114	              indexes -> $1 = to_jsonb($2::text)
115	              OR (
116	                jsonb_typeof(indexes -> $1) = 'array'
117	                AND (indexes -> $1) ? $2
118	              )
119	            )
120	          ORDER BY key
121	          LIMIT $4`,
122	        [input.index, input.value, after, limit + 1],
123	      );
124	      const page = result.rows.slice(0, limit);
125	      const last = page.at(-1);
126	      return {
127	        records: page.map(record),
128	        ...(result.rows.length > limit && last
129	          ? { cursor: encodeURIComponent(last.key) }
130	          : {}),
131	      };
132	    },
133	  };
134	}
  1	import { z } from "zod";
  2	
  3	export const PRODUCTION_APP_AUTHORITY = "https://app.skillplane.dev";
  4	export const PRODUCTION_MCP_RESOURCE = "https://mcp.skillplane.dev/mcp";
  5	
  6	const identifier = z
  7	  .string()
  8	  .min(1)
  9	  .max(80)
 10	  .regex(/^[a-z][a-z0-9-]*$/u);
 11	const bindingName = z
 12	  .string()
 13	  .min(1)
 14	  .max(64)
 15	  .regex(/^[A-Z][A-Z0-9_]*$/u);
 16	function secureOrLoopback(parsed: URL): boolean {
 17	  return (
 18	    parsed.protocol === "https:" ||
 19	    (parsed.protocol === "http:" &&
 20	      ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname))
 21	  );
 22	}
 23	
 24	const authority = z.url().refine((value) => {
 25	  const parsed = new URL(value);
 26	  return (
 27	    secureOrLoopback(parsed) &&
 28	    !parsed.username &&
 29	    !parsed.password &&
 30	    !parsed.search &&
 31	    !parsed.hash &&
 32	    parsed.pathname === "/"
 33	  );
 34	}, "must be a secure or loopback origin without credentials, path, query, or fragment");
 35	const mcpResource = z.url().refine((value) => {
 36	  const parsed = new URL(value);
 37	  return (
 38	    secureOrLoopback(parsed) &&
 39	    !parsed.username &&
 40	    !parsed.password &&
 41	    !parsed.search &&
 42	    !parsed.hash &&
 43	    parsed.pathname === "/mcp"
 44	  );
 45	}, "must be a secure or loopback /mcp resource URL");
 46	
 47	const cellSchema = z
 48	  .object({
 49	    regionId: identifier,
 50	    databaseBinding: bindingName,
 51	    objectStorageBinding: bindingName,
 52	    appServiceBinding: bindingName,
 53	    mcpServiceBinding: bindingName,
 54	    publiclyRoutable: z.literal(false),
 55	  })
 56	  .strict();
 57	
 58	const topologySchema = z
 59	  .object({
 60	    version: z.literal(1),
 61	    mode: z.enum(["single-cell", "multi-cell"]),
 62	    public: z
 63	      .object({
 64	        appAuthority: authority,
 65	        mcpResource,
 66	      })
 67	      .strict(),
 68	    controlPlane: z
 69	      .object({
 70	        regionId: identifier,
 71	        databaseBinding: bindingName,
 72	        publicObjectStorageBinding: bindingName,
 73	        issuer: authority,
 74	        oauthResource: mcpResource,
 75	      })
 76	      .strict(),
 77	    cells: z.array(cellSchema).min(1),
 78	    routing: z
 79	      .object({
 80	        activeKeyId: identifier,
 81	        verificationKeyIds: z.array(identifier).min(1),
 82	        assertionAudience: identifier,
 83	        assertionTtlSeconds: z.number().int().min(1).max(60),
 84	      })
 85	      .strict(),
 86	  })
 87	  .strict();
 88	
 89	export type SkillplaneTopologyManifest = z.infer<typeof topologySchema>;
 90	export type RegionalCellManifest = SkillplaneTopologyManifest["cells"][number];
 91	
 92	export type TopologyErrorCode =
 93	  | "TOPOLOGY_INVALID"
 94	  | "TOPOLOGY_DUPLICATE_REGION"
 95	  | "TOPOLOGY_DUPLICATE_BINDING"
 96	  | "TOPOLOGY_REGION_COUNT_INVALID"
 97	  | "TOPOLOGY_ISSUER_DRIFT"
 98	  | "TOPOLOGY_KEY_ROTATION_INVALID";
 99	
100	export class TopologyError extends Error {
101	  readonly code: TopologyErrorCode;
102	  readonly fields: readonly string[];
103	
104	  constructor(code: TopologyErrorCode, message: string, fields: readonly string[]) {
105	    super(message);
106	    this.name = "TopologyError";
107	    this.code = code;
108	    this.fields = fields;
109	  }
110	}
111	
112	function duplicates(values: readonly string[]): string[] {
113	  const seen = new Set<string>();
114	  const found = new Set<string>();
115	  for (const value of values) {
116	    if (seen.has(value)) found.add(value);
117	    seen.add(value);
118	  }
119	  return [...found].sort();
120	}
121	
122	export function parseTopologyManifest(
123	  input: unknown,
124	  options: { readonly production?: boolean } = {},
125	): SkillplaneTopologyManifest {
126	  let raw: unknown = input;
127	  if (typeof input === "string") {
128	    try {
129	      raw = JSON.parse(input);
130	    } catch {
131	      throw new TopologyError(
132	        "TOPOLOGY_INVALID",
133	        "The topology manifest is not valid JSON",
134	        ["SKILLPLANE_TOPOLOGY"],
135	      );
136	    }
137	  }
138	  const parsed = topologySchema.safeParse(raw);
139	  if (!parsed.success) {
140	    throw new TopologyError(
141	      "TOPOLOGY_INVALID",
142	      "The topology manifest violates its schema",
143	      parsed.error.issues.map((issue) => issue.path.join(".") || "manifest"),
144	    );
145	  }
146	  const manifest = parsed.data;
147	  const duplicateRegions = duplicates(manifest.cells.map((cell) => cell.regionId));
148	  if (
149	    duplicateRegions.length > 0 ||
150	    manifest.cells.some((cell) => cell.regionId === manifest.controlPlane.regionId)
151	  ) {
152	    throw new TopologyError(
153	      "TOPOLOGY_DUPLICATE_REGION",
154	      "Control-plane and regional cell IDs must be unique",
155	      ["controlPlane.regionId", "cells.regionId"],
156	    );
157	  }
158	  if (
159	    (manifest.mode === "multi-cell" && manifest.cells.length < 2) ||
160	    (manifest.mode === "single-cell" && manifest.cells.length !== 1)
161	  ) {
162	    throw new TopologyError(
163	      "TOPOLOGY_REGION_COUNT_INVALID",
164	      "The topology mode does not match its regional cell count",
165	      ["mode", "cells"],
166	    );
167	  }
168	  const allBindings = [
169	    manifest.controlPlane.databaseBinding,
170	    manifest.controlPlane.publicObjectStorageBinding,
171	    ...manifest.cells.flatMap((cell) => [
172	      cell.databaseBinding,
173	      cell.objectStorageBinding,
174	      cell.appServiceBinding,
175	      cell.mcpServiceBinding,
176	    ]),
177	  ];
178	  if (duplicates(allBindings).length > 0) {
179	    throw new TopologyError(
180	      "TOPOLOGY_DUPLICATE_BINDING",
181	      "Every database, storage, and service binding must have one owner",
182	      ["controlPlane", "cells"],
183	    );
184	  }
185	  if (
186	    manifest.public.appAuthority !== manifest.controlPlane.issuer ||
187	    manifest.public.mcpResource !== manifest.controlPlane.oauthResource ||
188	    (options.production &&
189	      (manifest.public.appAuthority !== PRODUCTION_APP_AUTHORITY ||
190	        manifest.public.mcpResource !== PRODUCTION_MCP_RESOURCE))
191	  ) {
192	    throw new TopologyError(
193	      "TOPOLOGY_ISSUER_DRIFT",
194	      "Public authorities and the control-plane OAuth identity must be canonical",
195	      ["public", "controlPlane.issuer", "controlPlane.oauthResource"],
196	    );
197	  }
198	  const keyIds = new Set(manifest.routing.verificationKeyIds);
199	  if (!keyIds.has(manifest.routing.activeKeyId) || keyIds.size > 3) {
200	    throw new TopologyError(
201	      "TOPOLOGY_KEY_ROTATION_INVALID",
202	      "The active routing key must be in the bounded verification keyring",
203	      ["routing.activeKeyId", "routing.verificationKeyIds"],
204	    );
205	  }
206	  return manifest;
207	}
208	
209	export function createSingleCellTopology(input: {
210	  readonly appAuthority: string;
211	  readonly mcpResource: string;
212	  readonly controlDatabaseBinding?: string;
213	  readonly publicObjectStorageBinding?: string;
214	  readonly regionId?: string;
215	  readonly regionalDatabaseBinding?: string;
216	  readonly regionalObjectStorageBinding?: string;
217	}): SkillplaneTopologyManifest {
218	  return parseTopologyManifest({
219	    version: 1,
220	    mode: "single-cell",
221	    public: {
222	      appAuthority: input.appAuthority,
223	      mcpResource: input.mcpResource,
224	    },
225	    controlPlane: {
226	      regionId: "global",
227	      databaseBinding: input.controlDatabaseBinding ?? "CONTROL_HYPERDRIVE",
228	      publicObjectStorageBinding:
229	        input.publicObjectStorageBinding ?? "PUBLIC_SKILL_BUNDLES",
230	      issuer: input.appAuthority,
231	      oauthResource: input.mcpResource,
232	    },
233	    cells: [
234	      {
235	        regionId: input.regionId ?? "local",
236	        databaseBinding: input.regionalDatabaseBinding ?? "CELL_HYPERDRIVE",
237	        objectStorageBinding:
238	          input.regionalObjectStorageBinding ?? "CELL_SKILL_BUNDLES",
239	        appServiceBinding: "CELL_APP",
240	        mcpServiceBinding: "CELL_MCP",
241	        publiclyRoutable: false,
242	      },
243	    ],
244	    routing: {
245	      activeKeyId: "current",
246	      verificationKeyIds: ["current"],
247	      assertionAudience: "skillplane-cell",
248	      assertionTtlSeconds: 20,
249	    },
250	  });
251	}

