144	export async function claimWorkspacePlacement(input: {
145	  readonly directory: WorkspacePlacementDirectory;
146	  readonly workspaceId: string;
147	  readonly regionId: string;
148	  readonly destinationRef?: string;
149	  readonly now?: () => number;
