160	export function createWorkspaceRoutingAssertions(input: {
161	  readonly activeKeyId: string;
162	  readonly keys: Readonly<Record<string, string | Uint8Array>>;
163	  readonly now?: () => number;
164	  readonly clockSkewMs?: number;
165	}): WorkspaceRoutingAssertionSigner & WorkspaceRoutingAssertionVerifier {
166	  return createDatafnHmacRoutingAssertions({
167	    activeKeyId: input.activeKeyId,
168	    keys: { ...input.keys },
169	    ...(input.now ? { now: input.now } : {}),
170	    ...(input.clockSkewMs === undefined ? {} : { clockSkewMs: input.clockSkewMs }),
171	  });
