 62	export function createWorkspaceGateway(input: {
 63	  readonly directory: WorkspacePlacementDirectory;
 64	  readonly resolveAuthorizedWorkspace: (request: Request) => Promise<string>;
 65	  readonly cells: RegionalCellRegistry;
 66	  readonly signer: WorkspaceRoutingAssertionSigner;
 67	  readonly assertionAudience: string;
 68	  readonly assertionTtlMs?: number;
 69	  readonly maxBodyBytes?: number;
 70	  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
 71	}): WorkspaceGateway {
 72	  const router: DatafnGatewayRouter = createDatafnGatewayRouter({
 73	    directory: input.directory,
 74	    deriveNamespace: input.resolveAuthorizedWorkspace,
 75	    cellRegistry: {
 76	      resolve: (target) => input.cells.resolve(target),
 77	    },
 78	    dispatcher: {
 79	      dispatch: ({ target, request, assertion, placement }) => {
 80	        const headers = new Headers(request.headers);
 81	        headers.set("x-datafn-routing-assertion", assertion);
 82	        headers.set("x-skillplane-routed-workspace-id", placement.namespace);
 83	        return target.fetch(
 84	          new Request(request, {
 85	            headers,
 86	          }),
 87	        );
 88	      },
 89	    },
