 93	      ? {}
 94	      : { assertionTtlMs: input.assertionTtlMs }),
 95	    ...(input.maxBodyBytes === undefined ? {} : { maxBodyBytes: input.maxBodyBytes }),
 96	    ...(input.onEvent ? { onEvent: input.onEvent } : {}),
 97	  });
