112	export function createRegionalWorkspaceGuard(input: {
113	  readonly regionId: string;
114	  readonly directory: WorkspacePlacementDirectory;
115	  readonly verifier: DatafnRoutingAssertionVerifier;
116	  readonly assertionAudience: string;
117	  readonly replayStore?: DatafnRoutingReplayStore;
118	  readonly now?: () => number;
119	  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
120	}): RegionalWorkspaceGuard {
121	  const replayStore =
122	    input.replayStore ??
123	    createMemoryDatafnRoutingReplayStore({
124	      ...(input.now ? { now: input.now } : {}),
125	    });
126	  return {
127	    async authorize(request, workspaceId) {
128	      const validated = await validateDatafnPlacement({
