  4	/** Atomic, cross-instance replay protection for signed gateway assertions. */
  5	export function createPostgresRoutingReplayStore(
  6	  sql: PlacementSqlClient,
  7	): DatafnRoutingReplayStore {
  8	  return {
  9	    async claim(nonce, expiresAt) {
 10	      const expiry = new Date(expiresAt);
 11	      if (!Number.isFinite(expiry.getTime()) || expiry.getTime() <= Date.now()) {
 12	        return false;
 13	      }
 14	      const result = await sql.query<{ nonce: string }>(
 15	        `INSERT INTO workspace_routing_nonces (nonce, expires_at)
 16	         VALUES ($1, $2)
 17	         ON CONFLICT (nonce) DO NOTHING
 18	         RETURNING nonce`,
 19	        [nonce, expiry],
 20	      );
 21	      return result.rows.length === 1;
 22	    },
 23	  };
 24	}
