 34	  return {
 35	    async resolve(resourceType, resourceId) {
 36	      const result = await sql.query<ResourceRouteRow>(
 37	        `SELECT resource_type, resource_id, workspace_id, state, updated_at
 38	           FROM resource_routing_directory
 39	          WHERE resource_type = $1 AND resource_id = $2 AND state = 'active'`,
