 16	function secureOrLoopback(parsed: URL): boolean {
 17	  return (
 18	    parsed.protocol === "https:" ||
 19	    (parsed.protocol === "http:" &&
 20	      ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname))
 21	  );
