 89	export type SkillplaneTopologyManifest = z.infer<typeof topologySchema>;
 90	export type RegionalCellManifest = SkillplaneTopologyManifest["cells"][number];
 91	
 92	export type TopologyErrorCode =
 93	  | "TOPOLOGY_INVALID"
 94	  | "TOPOLOGY_DUPLICATE_REGION"
 95	  | "TOPOLOGY_DUPLICATE_BINDING"
 96	  | "TOPOLOGY_REGION_COUNT_INVALID"
 97	  | "TOPOLOGY_ISSUER_DRIFT"
 98	  | "TOPOLOGY_KEY_ROTATION_INVALID";
 99	
100	export class TopologyError extends Error {
101	  readonly code: TopologyErrorCode;
102	  readonly fields: readonly string[];
103	
104	  constructor(code: TopologyErrorCode, message: string, fields: readonly string[]) {
105	    super(message);
106	    this.name = "TopologyError";
107	    this.code = code;
108	    this.fields = fields;
109	  }
110	}
111	
112	function duplicates(values: readonly string[]): string[] {
113	  const seen = new Set<string>();
114	  const found = new Set<string>();
115	  for (const value of values) {
116	    if (seen.has(value)) found.add(value);
117	    seen.add(value);
118	  }
119	  return [...found].sort();
120	}
121	
122	export function parseTopologyManifest(
123	  input: unknown,
124	  options: { readonly production?: boolean } = {},
125	): SkillplaneTopologyManifest {
126	  let raw: unknown = input;
127	  if (typeof input === "string") {
128	    try {
129	      raw = JSON.parse(input);
130	    } catch {
131	      throw new TopologyError(
132	        "TOPOLOGY_INVALID",
133	        "The topology manifest is not valid JSON",
134	        ["SKILLPLANE_TOPOLOGY"],
135	      );
136	    }
137	  }
138	  const parsed = topologySchema.safeParse(raw);
139	  if (!parsed.success) {
140	    throw new TopologyError(
141	      "TOPOLOGY_INVALID",
142	      "The topology manifest violates its schema",
143	      parsed.error.issues.map((issue) => issue.path.join(".") || "manifest"),
144	    );
145	  }
146	  const manifest = parsed.data;
147	  const duplicateRegions = duplicates(manifest.cells.map((cell) => cell.regionId));
148	  if (
149	    duplicateRegions.length > 0 ||
150	    manifest.cells.some((cell) => cell.regionId === manifest.controlPlane.regionId)
151	  ) {
152	    throw new TopologyError(
153	      "TOPOLOGY_DUPLICATE_REGION",
154	      "Control-plane and regional cell IDs must be unique",
155	      ["controlPlane.regionId", "cells.regionId"],
156	    );
157	  }
158	  if (
159	    (manifest.mode === "multi-cell" && manifest.cells.length < 2) ||
160	    (manifest.mode === "single-cell" && manifest.cells.length !== 1)
161	  ) {
162	    throw new TopologyError(
163	      "TOPOLOGY_REGION_COUNT_INVALID",
164	      "The topology mode does not match its regional cell count",
165	      ["mode", "cells"],
166	    );
167	  }
168	  const allBindings = [
169	    manifest.controlPlane.databaseBinding,
170	    manifest.controlPlane.publicObjectStorageBinding,
171	    ...manifest.cells.flatMap((cell) => [
172	      cell.databaseBinding,
173	      cell.objectStorageBinding,
174	      cell.appServiceBinding,
175	      cell.mcpServiceBinding,
176	    ]),
177	  ];
178	  if (duplicates(allBindings).length > 0) {
179	    throw new TopologyError(
180	      "TOPOLOGY_DUPLICATE_BINDING",
181	      "Every database, storage, and service binding must have one owner",
182	      ["controlPlane", "cells"],
183	    );
184	  }
185	  if (
186	    manifest.public.appAuthority !== manifest.controlPlane.issuer ||
187	    manifest.public.mcpResource !== manifest.controlPlane.oauthResource ||
188	    (options.production &&
189	      (manifest.public.appAuthority !== PRODUCTION_APP_AUTHORITY ||
190	        manifest.public.mcpResource !== PRODUCTION_MCP_RESOURCE))
191	  ) {
192	    throw new TopologyError(
193	      "TOPOLOGY_ISSUER_DRIFT",
194	      "Public authorities and the control-plane OAuth identity must be canonical",
195	      ["public", "controlPlane.issuer", "controlPlane.oauthResource"],
196	    );
197	  }
198	  const keyIds = new Set(manifest.routing.verificationKeyIds);
199	  if (!keyIds.has(manifest.routing.activeKeyId) || keyIds.size > 3) {
200	    throw new TopologyError(
201	      "TOPOLOGY_KEY_ROTATION_INVALID",
202	      "The active routing key must be in the bounded verification keyring",
203	      ["routing.activeKeyId", "routing.verificationKeyIds"],
204	    );
205	  }
206	  return manifest;
207	}
