 80	/** PostgreSQL is the linearizable global authority for workspace placement. */
 81	export function createPostgresWorkspacePlacementDirectory(
 82	  sql: PlacementSqlClient,
 83	): WorkspacePlacementDirectory {
 84	  const get = async (namespace: string): Promise<WorkspacePlacement | null> => {
