174	/** Stable fallback placement policy; deployments may override it with latency policy. */
175	export function selectInitialWorkspaceRegion(
176	  workspaceKey: string,
177	  regionIds: readonly string[],
178	): string {
179	  const regions = [...new Set(regionIds)].sort();
180	  if (regions.length === 0) throw new Error("WORKSPACE_REGION_UNAVAILABLE");
181	  let hash = 2_166_136_261;
182	  for (const byte of new TextEncoder().encode(workspaceKey)) {
183	    hash ^= byte;
184	    hash = Math.imul(hash, 16_777_619) >>> 0;
185	  }
186	  const selected = regions[hash % regions.length];
187	  if (!selected) throw new Error("WORKSPACE_REGION_UNAVAILABLE");
188	  return selected;
189	}
