  7	interface DirectoryRow extends Record<string, unknown> {
  8	  readonly key: string;
  9	  readonly value: string;
 10	  readonly indexes: Record<string, string | readonly string[] | null> | null;
 11	  readonly expires_at: Date | string | null;
 12	}
 13	
 14	function record(row: DirectoryRow): IndexedDirectoryRecord {
 15	  const ttlSeconds = row.expires_at
 16	    ? Math.max(0, Math.ceil((new Date(row.expires_at).getTime() - Date.now()) / 1_000))
 17	    : undefined;
 18	  return {
 19	    key: row.key,
 20	    value: row.value,
 21	    ...(row.indexes ? { indexes: row.indexes } : {}),
 22	    ...(ttlSeconds === undefined ? {} : { ttlSeconds }),
 23	  };
 24	}
 25	
 26	function expiry(ttlSeconds: number | undefined): Date | null {
 27	  if (ttlSeconds === undefined) return null;
 28	  if (!Number.isSafeInteger(ttlSeconds) || ttlSeconds < 1) {
 29	    throw new Error("PERMISSION_DIRECTORY_TTL_INVALID");
 30	  }
 31	  return new Date(Date.now() + ttlSeconds * 1_000);
 32	}
