 34	/** Durable global projection for DataFn permission-directory plugins. */
 35	export function createPostgresPermissionDirectory(
 36	  sql: PlacementSqlClient,
 37	): IndexedDirectoryStoreAdapter {
 38	  const get = async (key: string): Promise<IndexedDirectoryRecord | null> => {
 39	    const result = await sql.query<DirectoryRow>(
 40	      `SELECT key, value, indexes, expires_at
 41	         FROM permission_directory_records
 42	        WHERE key = $1 AND (expires_at IS NULL OR expires_at > now())`,
 43	      [key],
 44	    );
 45	    const row = result.rows[0];
 46	    return row ? record(row) : null;
 47	  };
 48	  return {
 49	    get,
 50	    async put(input) {
 51	      await sql.query(
 52	        `INSERT INTO permission_directory_records
 53	           (key, value, indexes, expires_at, updated_at)
 54	         VALUES ($1, $2, $3::jsonb, $4, now())
 55	         ON CONFLICT (key)
 56	         DO UPDATE SET value = EXCLUDED.value, indexes = EXCLUDED.indexes,
 57	                       expires_at = EXCLUDED.expires_at, updated_at = now()`,
 58	        [
 59	          input.key,
 60	          input.value,
 61	          JSON.stringify(input.indexes ?? {}),
 62	          expiry(input.ttlSeconds),
 63	        ],
 64	      );
 65	    },
 66	    async putIfAbsent(input) {
 67	      const result = await sql.query<DirectoryRow>(
 68	        `INSERT INTO permission_directory_records
 69	           (key, value, indexes, expires_at, updated_at)
 70	         VALUES ($1, $2, $3::jsonb, $4, now())
 71	         ON CONFLICT (key) DO NOTHING
 72	         RETURNING key, value, indexes, expires_at`,
 73	        [
 74	          input.key,
 75	          input.value,
 76	          JSON.stringify(input.indexes ?? {}),
 77	          expiry(input.ttlSeconds),
 78	        ],
 79	      );
 80	      if (result.rows[0]) return { inserted: true };
 81	      const existing = await get(input.key);
 82	      return existing ? { inserted: false, existing } : { inserted: false };
 83	    },
 84	    async update(input) {
 85	      const result = await sql.query<DirectoryRow>(
 86	        `UPDATE permission_directory_records
 87	            SET value = $2, indexes = $3::jsonb, expires_at = $4,
 88	                updated_at = now()
 89	          WHERE key = $1
 90	          RETURNING key, value, indexes, expires_at`,
 91	        [
 92	          input.key,
 93	          input.value,
 94	          JSON.stringify(input.indexes ?? {}),
 95	          expiry(input.ttlSeconds),
 96	        ],
 97	      );
 98	      const row = result.rows[0];
 99	      if (!row) throw new Error("PERMISSION_DIRECTORY_RECORD_NOT_FOUND");
100	      return record(row);
101	    },
102	    async delete(key) {
103	      await sql.query("DELETE FROM permission_directory_records WHERE key = $1", [key]);
104	    },
105	    async query(input) {
106	      const limit = Math.min(Math.max(input.limit ?? 100, 1), 100);
107	      const after = input.cursor ? decodeURIComponent(input.cursor) : "";
108	      const result = await sql.query<DirectoryRow>(
109	        `SELECT key, value, indexes, expires_at
110	           FROM permission_directory_records
111	          WHERE key > $3
112	            AND (expires_at IS NULL OR expires_at > now())
113	            AND (
114	              indexes -> $1 = to_jsonb($2::text)
115	              OR (
116	                jsonb_typeof(indexes -> $1) = 'array'
117	                AND (indexes -> $1) ? $2
118	              )
119	            )
120	          ORDER BY key
121	          LIMIT $4`,
122	        [input.index, input.value, after, limit + 1],
123	      );
124	      const page = result.rows.slice(0, limit);
125	      const last = page.at(-1);
126	      return {
127	        records: page.map(record),
128	        ...(result.rows.length > limit && last
129	          ? { cursor: encodeURIComponent(last.key) }
130	          : {}),
131	      };
132	    },
133	  };
134	}
