112	function duplicates(values: readonly string[]): string[] {
113	  const seen = new Set<string>();
114	  const found = new Set<string>();
115	  for (const value of values) {
116	    if (seen.has(value)) found.add(value);
117	    seen.add(value);
118	  }
119	  return [...found].sort();
120	}
