174	export async function migrateWorkspaceWithJournal(
175	  input: Parameters<typeof migrateWorkspace>[0] & {
176	    readonly journal: WorkspaceMigrationJournal;
177	    readonly migrationId?: string;
178	  },
179	): Promise<{
180	  readonly migrationId: string;
181	  readonly placement: WorkspacePlacement;
182	  readonly proof: WorkspaceMigrationProof;
183	}> {
184	  const source = await input.directory.get(input.workspaceId);
185	  if (source?.state !== "active") {
186	    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
187	  }
188	  const migrationId = input.migrationId ?? `workspace-migration:${crypto.randomUUID()}`;
189	  await input.journal.started({
190	    id: migrationId,
191	    workspaceId: input.workspaceId,
192	    sourceRegionId: source.regionId,
193	    targetRegionId: input.targetRegionId,
194	    sourceEpoch: source.epoch,
195	  });
196	  try {
197	    const result = await migrateWorkspace(input);
198	    await input.journal.completed(migrationId, result.proof);
199	    return { migrationId, ...result };
