201	    const code =
202	      error instanceof Error && /^[A-Z0-9_:-]{1,160}$/u.test(error.message)
203	        ? error.message
204	        : "WORKSPACE_MIGRATION_FAILED";
205	    await input.journal.failed(migrationId, code).catch(() => undefined);
206	    throw error;
207	  }
208	}
  1	export function globalPublishedBundleKey(input: {
  2	  readonly workspaceId: string;
  3	  readonly skillId: string;
  4	  readonly versionId: string;
  5	  readonly digest: `sha256:${string}`;
  6	}): string {
  7	  const safe = (value: string, label: string): string => {
  8	    if (!/^[A-Za-z0-9:_-]{1,180}$/u.test(value)) {
  9	      throw new Error(`PUBLICATION_${label.toUpperCase()}_INVALID`);
 10	    }
 11	    return value;
 12	  };
 13	  const digest = input.digest.slice("sha256:".length);
 14	  if (!/^[a-f0-9]{64}$/u.test(digest)) {
 15	    throw new Error("PUBLICATION_DIGEST_INVALID");
 16	  }
 17	  return [
 18	    "public",
 19	    "workspaces",
 20	    safe(input.workspaceId, "workspace"),
 21	    "skills",
 22	    safe(input.skillId, "skill"),
 23	    "versions",
 24	    safe(input.versionId, "version"),
 25	    "sha256",
 26	    `${digest}.zip`,
 27	  ].join("/");
 28	}
