 59	/** Adapts a private R2-compatible bucket to the immutable projection contract. */
 60	export function createImmutableObjectPublicationStore(
 61	  bucket: ImmutableObjectBucket,
 62	): ImmutablePublicationStore {
 63	  return {
 64	    async putIfAbsent(input) {
 65	      if (await bucket.head(input.key)) return "exists";
 66	      const created = await bucket.put(input.key, input.bytes, {
 67	        onlyIf: { etagDoesNotMatch: "*" },
 68	        httpMetadata: { contentType: "application/zip" },
 69	        customMetadata: { ...input.metadata, digest: input.digest },
 70	      });
 71	      return created ? "created" : "exists";
 72	    },
 73	    async read(input) {
 74	      const object = await bucket.get(input.key);
 75	      if (!object) throw new Error("PUBLICATION_OBJECT_NOT_FOUND");
 76	      return new Uint8Array(await object.arrayBuffer());
 77	    },
 78	    delete: (key) => bucket.delete(key),
 79	  };
 80	}
