 60	function safeFailureCode(error: unknown): string {
 61	  const message = error instanceof Error ? error.message : "UNKNOWN";
 62	  return /^[A-Z0-9_:-]{1,160}$/u.test(message)
 63	    ? message
 64	    : "PUBLICATION_PROJECTION_FAILED";
