 67	/**
 68	 * Claims at most one ordered event per workspace, then acknowledges each event
 69	 * only after the global projection succeeds. Expired claims are recoverable and
 70	 * the projection itself is idempotent, so worker termination cannot expose a
 71	 * partially copied bundle.
 72	 */
 73	export async function drainRegionalProjectionOutbox(input: {
 74	  readonly regionId: string;
 75	  readonly database: ProjectionOutboxSqlClient;
 76	  readonly process: (event: RegionalProjectionEvent) => Promise<void>;
 77	  readonly limit?: number;
 78	  readonly leaseSeconds?: number;
 79	  readonly claimToken?: string;
 80	  readonly onEvent?: (event: {
 81	    readonly type: "processed" | "failed";
 82	    readonly eventId: string;
 83	    readonly errorCode?: string;
 84	  }) => void | Promise<void>;
 85	}): Promise<{ readonly processed: number; readonly failed: number }> {
 86	  const limit = input.limit ?? 50;
 87	  const leaseSeconds = input.leaseSeconds ?? 60;
 88	  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 500) {
 89	    throw new Error("PUBLICATION_OUTBOX_LIMIT_INVALID");
 90	  }
 91	  if (!Number.isSafeInteger(leaseSeconds) || leaseSeconds < 10 || leaseSeconds > 600) {
 92	    throw new Error("PUBLICATION_OUTBOX_LEASE_INVALID");
 93	  }
 94	  const claimToken = input.claimToken ?? `projection-claim:${crypto.randomUUID()}`;
 95	  const claimed = await input.database.query(
 96	    `WITH candidates AS (
 97	       SELECT candidate.id
 98	         FROM regional_projection_outbox candidate
 99	        WHERE candidate.processed_at IS NULL
100	          AND (candidate.claimed_at IS NULL OR
101	               candidate.claimed_at < now() - ($2::integer * interval '1 second'))
102	          AND NOT EXISTS (
103	            SELECT 1
104	              FROM regional_projection_outbox earlier
105	             WHERE earlier.workspace_id = candidate.workspace_id
106	               AND earlier.processed_at IS NULL
107	               AND earlier.sequence < candidate.sequence
108	          )
109	        ORDER BY candidate.created_at, candidate.id
110	        LIMIT $1
111	        FOR UPDATE SKIP LOCKED
112	     )
113	     UPDATE regional_projection_outbox event
114	        SET claim_token = $3, claimed_at = now(), attempts = attempts + 1
115	       FROM candidates
116	      WHERE event.id = candidates.id
117	      RETURNING event.id, event.workspace_id, event.event_type,
118	                event.payload, event.fencing_epoch`,
119	    [limit, leaseSeconds, claimToken],
120	  );
121	  let processed = 0;
122	  let failed = 0;
123	  for (const row of claimed.rows as readonly ProjectionOutboxRow[]) {
124	    const event: RegionalProjectionEvent = {
125	      id: row.id,
126	      regionId: input.regionId,
127	      eventType: eventType.parse(row.event_type),
128	      workspaceId: row.workspace_id,
129	      fencingEpoch: row.fencing_epoch,
130	      payload: row.payload,
131	    };
132	    try {
133	      await input.process(event);
134	      const acknowledged = await input.database.query(
135	        `UPDATE regional_projection_outbox
136	            SET processed_at = now(), claim_token = NULL, claimed_at = NULL,
137	                last_error = NULL
138	          WHERE id = $1 AND claim_token = $2 AND processed_at IS NULL
139	          RETURNING id`,
140	        [row.id, claimToken],
141	      );
142	      if (acknowledged.rows.length !== 1) {
143	        throw new Error("PUBLICATION_OUTBOX_CLAIM_LOST");
144	      }
145	      processed += 1;
146	      await input.onEvent?.({ type: "processed", eventId: row.id });
147	    } catch (error) {
148	      const errorCode = safeFailureCode(error);
149	      await input.database.query(
150	        `UPDATE regional_projection_outbox
151	            SET claim_token = NULL, claimed_at = NULL, last_error = $3
152	          WHERE id = $1 AND claim_token = $2 AND processed_at IS NULL`,
153	        [row.id, claimToken, errorCode],
154	      );
155	      failed += 1;
156	      await input.onEvent?.({ type: "failed", eventId: row.id, errorCode });
157	    }
158	  }
159	  return { processed, failed };
160	}
