103	/** Composes Skillplane copy/verification hooks with DataFn's fenced move state machine. */
104	export async function migrateWorkspace(input: {
105	  readonly directory: WorkspacePlacementDirectory;
106	  readonly workspaceId: string;
107	  readonly targetRegionId: string;
108	  readonly targetDestinationRef?: string;
109	  readonly operations: WorkspaceMigrationOperations;
110	  readonly now?: () => number;
111	  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
112	}): Promise<{
113	  readonly placement: WorkspacePlacement;
114	  readonly proof: WorkspaceMigrationProof;
115	}> {
116	  const now = input.now ?? Date.now;
117	  const before = await input.directory.get(input.workspaceId);
118	  if (before?.state !== "active") {
119	    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
120	  }
121	  const startedAt = new Date(now()).toISOString();
122	  const checks: MigrationCheck[] = [];
123	  const placement = await migrateDatafnNamespace({
124	    directory: input.directory,
125	    namespace: input.workspaceId,
126	    targetRegionId: input.targetRegionId,
127	    ...(input.targetDestinationRef
128	      ? { targetDestinationRef: input.targetDestinationRef }
129	      : {}),
130	    hooks: {
131	      quiesceSource: (context) => input.operations.quiesceSource(context),
132	      drainPermissionDirectory: (context) => input.operations.drainOutboxes(context),
133	      async copyTenantData(context) {
134	        await input.operations.copyDatabase(context);
135	        await input.operations.copyBundles(context);
136	      },
137	      async validateTenantData(context) {
138	        checks.push(...(await input.operations.verifyDatabase(context)));
139	        checks.push(...(await input.operations.verifyBundles(context)));
140	        if (checks.length === 0 || checks.some((check) => !check.matched)) {
141	          throw new Error("WORKSPACE_MIGRATION_VERIFICATION_FAILED");
142	        }
143	      },
144	      rebuildPermissionDirectory: (context) =>
145	        input.operations.rebuildGlobalResourceDirectory(context),
146	      warmTarget: (context) => input.operations.warmTarget(context),
147	      resumeTarget: (context) => input.operations.resumeTarget(context),
148	      rollbackSource: (context) => input.operations.rollbackSource(context),
149	    },
150	    now,
151	    onEvent:
152	      input.onEvent ??
153	      ((event) => {
154	        logWorkspaceRoutingEvent("migration", event);
155	      }),
156	  });
157	  return {
158	    placement,
159	    proof: {
160	      workspaceId: input.workspaceId,
161	      sourceRegionId: before.regionId,
162	      targetRegionId: input.targetRegionId,
163	      sourceEpoch: before.epoch,
164	      finalEpoch: placement.epoch,
165	      startedAt,
166	      completedAt: new Date(now()).toISOString(),
167	      checks,
168	      rollbackTested: false,
169	    },
170	  };
171	}
