154	async function sha256(bytes: Uint8Array): Promise<`sha256:${string}`> {
155	  const copy = new Uint8Array(bytes.byteLength);
156	  copy.set(bytes);
157	  const digest = await crypto.subtle.digest("SHA-256", copy.buffer);
158	  return `sha256:${[...new Uint8Array(digest)]
159	    .map((byte) => byte.toString(16).padStart(2, "0"))
160	    .join("")}`;
161	}
