163	/** Copies an immutable regional bundle before atomically exposing its global projection. */
164	export async function publishGlobalProjection(input: {
165	  readonly source: ImmutablePublicationStore;
166	  readonly destination: ImmutablePublicationStore;
167	  readonly directory: PublicProjectionDirectory;
168	  readonly sourceKey: string;
169	  readonly workspaceId: string;
170	  readonly workspaceSlug: string;
171	  readonly skillId: string;
172	  readonly skillSlug: string;
173	  readonly versionId: string;
174	  readonly semanticVersion: string;
175	  readonly digest: `sha256:${string}`;
176	  readonly document?: Readonly<Record<string, unknown>>;
177	  readonly searchText?: string;
178	}): Promise<string> {
179	  const bytes = await input.source.read({ key: input.sourceKey, digest: input.digest });
180	  if ((await sha256(bytes)) !== input.digest) {
181	    throw new Error("PUBLICATION_SOURCE_DIGEST_MISMATCH");
182	  }
183	  const objectKey = globalPublishedBundleKey(input);
184	  await input.destination.putIfAbsent({
185	    key: objectKey,
186	    bytes,
187	    digest: input.digest,
188	    metadata: {
189	      workspaceId: input.workspaceId,
190	      skillId: input.skillId,
191	      versionId: input.versionId,
192	      digest: input.digest,
193	    },
194	  });
195	  const verified = await input.destination.read({
196	    key: objectKey,
197	    digest: input.digest,
198	  });
199	  if ((await sha256(verified)) !== input.digest) {
200	    throw new Error("PUBLICATION_DESTINATION_DIGEST_MISMATCH");
201	  }
202	  await input.directory.publish({
203	    workspaceId: input.workspaceId,
204	    workspaceSlug: input.workspaceSlug,
205	    skillId: input.skillId,
206	    skillSlug: input.skillSlug,
207	    versionId: input.versionId,
208	    semanticVersion: input.semanticVersion,
209	    digest: input.digest,
210	    objectKey,
211	    ...(input.document ? { document: input.document } : {}),
212	    ...(input.searchText !== undefined ? { searchText: input.searchText } : {}),
213	  });
214	  return objectKey;
215	}
