162	/**
163	 * Applies a regional publication event only while its placement epoch is
164	 * current. Stale cells therefore cannot republish after a workspace move.
165	 */
166	export async function applyRegionalPublicProjection(input: {
167	  readonly event: RegionalProjectionEvent;
168	  readonly placements: WorkspacePlacementDirectory;
169	  readonly resolveWorkspaceSlug: (workspaceId: string) => Promise<string | null>;
170	  readonly regionalStore: ImmutablePublicationStore;
171	  readonly publicStore: ImmutablePublicationStore;
172	  readonly directory: PublicProjectionDirectory;
173	}): Promise<{ readonly objectKey: string | null }> {
174	  const placement = await input.placements.get(input.event.workspaceId);
175	  if (
176	    placement?.state !== "active" ||
177	    placement.regionId !== input.event.regionId ||
178	    placement.epoch !== input.event.fencingEpoch
179	  ) {
180	    throw new Error("PUBLICATION_FENCING_EPOCH_STALE");
181	  }
182	  if (input.event.eventType === "public_skill.unpublished") {
183	    const payload = unpublishedPayload.parse(input.event.payload);
184	    if (payload.workspaceId !== input.event.workspaceId) {
185	      throw new Error("PUBLICATION_WORKSPACE_MISMATCH");
186	    }
187	    await input.directory.unpublish(payload);
188	    return { objectKey: null };
189	  }
190	  const payload = publishedPayload.parse(input.event.payload);
191	  if (payload.workspaceId !== input.event.workspaceId) {
192	    throw new Error("PUBLICATION_WORKSPACE_MISMATCH");
193	  }
194	  const workspaceSlug = await input.resolveWorkspaceSlug(payload.workspaceId);
195	  if (!workspaceSlug) throw new Error("PUBLICATION_WORKSPACE_NOT_FOUND");
196	  const objectKey = await publishGlobalProjection({
197	    source: input.regionalStore,
198	    destination: input.publicStore,
199	    directory: input.directory,
200	    sourceKey: payload.sourceObjectKey,
201	    workspaceId: payload.workspaceId,
202	    workspaceSlug,
203	    skillId: payload.skillId,
204	    skillSlug: payload.skillSlug,
205	    versionId: payload.versionId,
206	    semanticVersion: payload.semanticVersion,
207	    digest: payload.digest as `sha256:${string}`,
208	    document: payload.document,
209	    searchText: payload.searchText,
210	  });
211	  return { objectKey };
212	}
