163	 * Applies a regional publication event only while its placement epoch is
164	 * current. Stale cells therefore cannot republish after a workspace move.
165	 */
166	export async function applyRegionalPublicProjection(input: {
167	  readonly event: RegionalProjectionEvent;
168	  readonly placements: WorkspacePlacementDirectory;
169	  readonly resolveWorkspaceSlug: (workspaceId: string) => Promise<string | null>;
170	  readonly regionalStore: ImmutablePublicationStore;
171	  readonly publicStore: ImmutablePublicationStore;
172	  readonly directory: PublicProjectionDirectory;
173	}): Promise<{ readonly objectKey: string | null }> {
174	  const placement = await input.placements.get(input.event.workspaceId);
175	  if (
