197	    source: input.regionalStore,
198	    destination: input.publicStore,
199	    directory: input.directory,
200	    sourceKey: payload.sourceObjectKey,
201	    workspaceId: payload.workspaceId,
202	    workspaceSlug,
203	    skillId: payload.skillId,
204	    skillSlug: payload.skillSlug,
205	    versionId: payload.versionId,
206	    semanticVersion: payload.semanticVersion,
207	    digest: payload.digest as `sha256:${string}`,
208	    document: payload.document,
209	    searchText: payload.searchText,
210	  });
211	  return { objectKey };
212	}
