154	const environmentSchema = z.enum(["local", "preview", "production"]);
155	const authModeSchema = z.enum(["disabled", "otp"]);
156	
157	function isRecord(value: unknown): value is Record<string, unknown> {
158	  return typeof value === "object" && value !== null;
159	}
160	
161	function hasFunction<K extends string>(
162	  value: unknown,
163	  key: K,
164	): value is Record<K, (...args: never[]) => unknown> {
165	  return isRecord(value) && typeof value[key] === "function";
166	}
167	
168	function isObjectStorageBinding(value: unknown): value is ObjectStorageBinding {
169	  return (
170	    hasFunction(value, "head") &&
171	    hasFunction(value, "get") &&
172	    hasFunction(value, "put") &&
173	    hasFunction(value, "delete") &&
174	    hasFunction(value, "list")
175	  );
176	}
177	
178	function isEmailServiceBinding(value: unknown): value is EmailServiceBinding {
179	  return hasFunction(value, "send");
180	}
181	
182	function isHyperdriveBinding(value: unknown): value is HyperdriveBinding {
183	  return (
184	    isRecord(value) &&
185	    typeof value.connectionString === "string" &&
186	    isPostgresUrl(value.connectionString)
187	  );
188	}
189	
190	function isPostgresUrl(value: string): boolean {
191	  try {
192	    const url = new URL(value);
193	    return (
194	      ["postgres:", "postgresql:"].includes(url.protocol) &&
195	      url.hostname.length > 0 &&
196	      url.username.length > 0 &&
197	      url.password.length > 0 &&
198	      url.pathname.length > 1
199	    );
200	  } catch {
201	    return false;
202	  }
203	}
204	
205	function readEnvironment(bindings: RuntimeBindings): RuntimeEnvironment {
206	  const result = environmentSchema.safeParse(bindings.RUNTIME_ENV);
207	  if (!result.success) {
208	    throw new ConfigError("CONFIG_INVALID", "Runtime environment is invalid", [
209	      "RUNTIME_ENV",
210	    ]);
211	  }
212	  return result.data;
213	}
214	
215	function validateDatabaseAdapter(bindings: RuntimeBindings): void {
216	  if ((bindings.DATABASE_ADAPTER ?? "postgres") !== "postgres") {
217	    throw new ConfigError(
218	      "DATABASE_ADAPTER_INVALID",
219	      "Only the Postgres database adapter is permitted",
220	      ["DATABASE_ADAPTER"],
221	    );
222	  }
223	}
224	
225	function validateCloudflareEmailProvider(
226	  bindings: RuntimeBindings,
227	  environment: RuntimeEnvironment,
228	): void {
229	  if (bindings.EMAIL_PROVIDER !== "cloudflare-email") {
230	    throw new ConfigError(
231	      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_ADAPTER_INVALID",
232	      "OTP authentication requires the Cloudflare Email Service provider",
233	      ["EMAIL_PROVIDER"],
234	    );
235	  }
236	}
