238	function parseEmailSender(
239	  value: string | undefined,
240	  environment: RuntimeEnvironment,
241	  missing: string[],
242	): string | null {
243	  const expectedAddress =
244	    environment === "production"
245	      ? "no-reply@auth.skillplane.dev"
246	      : "no-reply@auth-dev.skillplane.dev";
247	  const normalized = value?.trim();
248	  const address = normalized
249	    ? (/^[^<>\r\n]+\s*<([^\s<>@]+@[^\s<>@]+)>$/.exec(normalized)?.[1] ??
250	      /^([^\s<>@]+@[^\s<>@]+)$/.exec(normalized)?.[1])
251	    : undefined;
252	  if (!normalized || address?.toLowerCase() !== expectedAddress) {
253	    missing.push("SKILLPLANE_OTP_FROM");
254	    return null;
255	  }
256	  return normalized;
257	}
258	
259	function parseSiteKey(value: string | undefined, missing: string[]): string | null {
260	  if (typeof value !== "string" || value.trim().length < 10) {
260	  if (typeof value !== "string" || value.trim().length < 10) {
261	    missing.push("PUBLIC_TURNSTILE_SITE_KEY");
262	    return null;
263	  }
264	  return value.trim();
265	}
266	
267	function parseAllowedHostnames(
268	  value: string | undefined,
269	  environment: RuntimeEnvironment,
270	  missing: string[],
271	): readonly string[] {
272	  const hostnames =
273	    value
274	      ?.split(",")
275	      .map((hostname) => hostname.trim().toLowerCase())
276	      .filter(Boolean) ?? [];
277	  if (
278	    hostnames.length === 0 ||
279	    hostnames.some(
280	      (hostname) =>
281	        !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(
282	          hostname,
283	        ),
284	    ) ||
285	    (environment !== "local" &&
286	      hostnames.some((hostname) => ["localhost", "127.0.0.1"].includes(hostname)))
287	  ) {
288	    missing.push("TURNSTILE_ALLOWED_HOSTNAMES");
289	    return [];
290	  }
291	  return [...new Set(hostnames)].sort();
292	}
293	
294	function readAuthMode(
295	  bindings: RuntimeBindings,
296	  environment: RuntimeEnvironment,
297	): "disabled" | "otp" {
298	  const result = authModeSchema.safeParse(bindings.AUTH_MODE);
299	  if (!result.success) {
300	    throw new ConfigError(
301	      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_ADAPTER_INVALID",
302	      "Authentication mode must be explicit",
303	      ["AUTH_MODE"],
304	    );
305	  }
306	  if (environment !== "local" && result.data !== "otp") {
307	    throw new ConfigError(
308	      "PRODUCTION_ADAPTER_INVALID",
309	      "Preview and production require OTP authentication",
310	      ["AUTH_MODE"],
311	    );
312	  }
313	  return result.data;
314	}
315	
316	function parseAuthConfiguration(
317	  bindings: RuntimeBindings,
318	  environment: RuntimeEnvironment,
319	): Pick<RuntimeConfig, "auth" | "email"> {
320	  const authMode = readAuthMode(bindings, environment);
321	  if (authMode === "disabled") {
322	    return { auth: null, email: null };
323	  }
324	  validateCloudflareEmailProvider(bindings, environment);
325	  const missing: string[] = [];
326	  if (!isEmailServiceBinding(bindings.SEND_EMAIL)) {
327	    missing.push("SEND_EMAIL");
328	  }
329	  const authfnSecret = requireSecret(bindings.AUTHFN_SECRET, "AUTHFN_SECRET", missing);
330	  const turnstileSecret = requireSecret(
331	    bindings.TURNSTILE_SECRET_KEY,
332	    "TURNSTILE_SECRET_KEY",
333	    missing,
334	  );
335	  const from = parseEmailSender(bindings.SKILLPLANE_OTP_FROM, environment, missing);
336	  const siteKey = parseSiteKey(bindings.PUBLIC_TURNSTILE_SITE_KEY, missing);
337	  const allowedHostnames = parseAllowedHostnames(
338	    bindings.TURNSTILE_ALLOWED_HOSTNAMES,
339	    environment,
340	    missing,
341	  );
342	  if (missing.length > 0) {
343	    throw new ConfigError(
344	      "PRODUCTION_BINDING_MISSING",
345	      "Required authentication bindings are unavailable",
346	      [...new Set(missing)].sort(),
347	    );
348	  }
349	  if (
350	    !isEmailServiceBinding(bindings.SEND_EMAIL) ||
351	    !authfnSecret ||
352	    !turnstileSecret ||
353	    !from ||
354	    !siteKey
355	  ) {
356	    throw new ConfigError(
357	      "PRODUCTION_BINDING_MISSING",
358	      "Required authentication bindings are unavailable",
359	      ["AUTH_CONFIGURATION"],
360	    );
361	  }
362	  return {
363	    email: {
364	      provider: "cloudflare-email",
365	      binding: bindings.SEND_EMAIL,
366	      from,
367	    },
368	    auth: {
369	      rateLimitPepper: authfnSecret,
370	      turnstile: {
371	        secretKey: turnstileSecret,
372	        siteKey,
373	        action: "otp_send",
374	        allowedHostnames,
375	      },
376	    },
377	  };
378	}
379	
380	function requireSecret(
381	  value: string | undefined,
382	  field: string,
383	  missing: string[],
384	): string | null {
385	  if (typeof value !== "string" || value.length < 32) {
386	    missing.push(field);
387	    return null;
388	  }
389	  return value;
390	}
