392	export interface OAuthEndpoints {
393	  readonly issuer: string;
394	  readonly resource: string;
395	}
396	
397	function parseOAuthUrl(
398	  value: string,
399	  field: "OAUTH_ISSUER" | "OAUTH_RESOURCE",
400	  environment: RuntimeEnvironment,
401	  productionValue: string,
402	  missing: string[],
403	): string | null {
404	  let parsed: URL;
405	  try {
406	    parsed = new URL(value);
407	  } catch {
408	    missing.push(field);
409	    return null;
410	  }
411	  const loopbackHttp =
412	    environment === "local" &&
413	    parsed.protocol === "http:" &&
414	    ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
415	  const normalized = parsed.toString().replace(/\/$/u, "");
416	  const canonicalPath =
417	    field === "OAUTH_ISSUER" ? parsed.pathname === "/" : parsed.pathname === "/mcp";
418	  if (
419	    parsed.username ||
420	    parsed.password ||
421	    parsed.search ||
422	    parsed.hash ||
423	    !canonicalPath ||
424	    (parsed.protocol !== "https:" && !loopbackHttp) ||
425	    (environment === "production" && normalized !== productionValue)
426	  ) {
427	    missing.push(field);
428	    return null;
429	  }
430	  return normalized;
431	}
432	
433	export function parseOAuthEndpoints(
434	  bindings: Pick<RuntimeBindings, "RUNTIME_ENV" | "OAUTH_ISSUER" | "OAUTH_RESOURCE">,
435	): OAuthEndpoints {
436	  const environment = readEnvironment(bindings);
437	  const missing: string[] = [];
438	  const issuer = parseOAuthUrl(
439	    bindings.OAUTH_ISSUER ??
440	      (environment === "local"
441	        ? "http://localhost:5700"
442	        : environment === "preview"
443	          ? "https://app-dev.skillplane.dev"
444	          : "https://app.skillplane.dev"),
445	    "OAUTH_ISSUER",
446	    environment,
447	    "https://app.skillplane.dev",
448	    missing,
449	  );
450	  const resource = parseOAuthUrl(
451	    bindings.OAUTH_RESOURCE ??
452	      (environment === "local"
453	        ? "http://127.0.0.1:5701/mcp"
454	        : environment === "preview"
455	          ? "https://mcp-dev.skillplane.dev/mcp"
456	          : "https://mcp.skillplane.dev/mcp"),
457	    "OAUTH_RESOURCE",
458	    environment,
459	    "https://mcp.skillplane.dev/mcp",
460	    missing,
461	  );
462	  if (missing.length > 0 || !issuer || !resource) {
463	    throw new ConfigError(
464	      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_BINDING_MISSING",
465	      "OAuth endpoint configuration is unavailable",
466	      [...new Set(missing)].sort((left, right) => left.localeCompare(right)),
467	    );
468	  }
469	  return { issuer, resource };
470	}
471	
472	function parseOAuthConfiguration(
473	  bindings: RuntimeBindings,
474	  environment: RuntimeEnvironment,
475	): RuntimeConfig["oauth"] {
476	  const missing: string[] = [];
477	  const tokenPepper =
478	    environment === "local" && bindings.OAUTH_TOKEN_PEPPER === undefined
479	      ? "skillplane-local-oauth-pepper-not-for-production"
480	      : requireSecret(bindings.OAUTH_TOKEN_PEPPER, "OAUTH_TOKEN_PEPPER", missing);
481	  const endpoints = parseOAuthEndpoints(bindings);
482	  if (missing.length > 0 || !tokenPepper) {
483	    throw new ConfigError(
484	      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_BINDING_MISSING",
485	      "OAuth authorization server configuration is unavailable",
486	      [...new Set(missing)].sort(),
487	    );
488	  }
489	  return {
490	    ...endpoints,
491	    tokenPepper,
492	  };
493	}
