397	function parseOAuthUrl(
398	  value: string,
399	  field: "OAUTH_ISSUER" | "OAUTH_RESOURCE",
400	  environment: RuntimeEnvironment,
401	  productionValue: string,
402	  missing: string[],
403	): string | null {
404	  let parsed: URL;
405	  try {
406	    parsed = new URL(value);
407	  } catch {
408	    missing.push(field);
409	    return null;
410	  }
411	  const loopbackHttp =
412	    environment === "local" &&
413	    parsed.protocol === "http:" &&
414	    ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
415	  const normalized = parsed.toString().replace(/\/$/u, "");
416	  const canonicalPath =
417	    field === "OAUTH_ISSUER" ? parsed.pathname === "/" : parsed.pathname === "/mcp";
418	  if (
419	    parsed.username ||
420	    parsed.password ||
421	    parsed.search ||
422	    parsed.hash ||
423	    !canonicalPath ||
424	    (parsed.protocol !== "https:" && !loopbackHttp) ||
425	    (environment === "production" && normalized !== productionValue)
426	  ) {
427	    missing.push(field);
428	    return null;
429	  }
430	  return normalized;
431	}
