433	export function parseOAuthEndpoints(
434	  bindings: Pick<RuntimeBindings, "RUNTIME_ENV" | "OAUTH_ISSUER" | "OAUTH_RESOURCE">,
435	): OAuthEndpoints {
436	  const environment = readEnvironment(bindings);
437	  const missing: string[] = [];
438	  const issuer = parseOAuthUrl(
439	    bindings.OAUTH_ISSUER ??
440	      (environment === "local"
441	        ? "http://localhost:5700"
442	        : environment === "preview"
443	          ? "https://app-dev.skillplane.dev"
444	          : "https://app.skillplane.dev"),
445	    "OAUTH_ISSUER",
446	    environment,
447	    "https://app.skillplane.dev",
448	    missing,
449	  );
450	  const resource = parseOAuthUrl(
451	    bindings.OAUTH_RESOURCE ??
452	      (environment === "local"
453	        ? "http://127.0.0.1:5701/mcp"
454	        : environment === "preview"
455	          ? "https://mcp-dev.skillplane.dev/mcp"
456	          : "https://mcp.skillplane.dev/mcp"),
457	    "OAUTH_RESOURCE",
458	    environment,
459	    "https://mcp.skillplane.dev/mcp",
460	    missing,
461	  );
462	  if (missing.length > 0 || !issuer || !resource) {
463	    throw new ConfigError(
464	      environment === "local" ? "CONFIG_INVALID" : "PRODUCTION_BINDING_MISSING",
465	      "OAuth endpoint configuration is unavailable",
466	      [...new Set(missing)].sort((left, right) => left.localeCompare(right)),
467	    );
468	  }
469	  return { issuer, resource };
470	}
