526	function routingKeys(
527	  bindings: RuntimeBindings,
528	  base: RuntimeBaseConfig,
529	  topology: SkillplaneTopologyManifest,
530	): RuntimeConfig["routing"] {
531	  let keys: Record<string, string> = {};
532	  if (typeof bindings.WORKSPACE_ROUTING_KEYS === "string") {
533	    try {
534	      const parsed: unknown = JSON.parse(bindings.WORKSPACE_ROUTING_KEYS);
535	      if (
536	        parsed &&
537	        typeof parsed === "object" &&
538	        !Array.isArray(parsed) &&
539	        Object.values(parsed).every(
540	          (value) => typeof value === "string" && value.length >= 32,
541	        )
542	      ) {
543	        keys = parsed as Record<string, string>;
544	      }
545	    } catch {
546	      // The stable diagnostic below deliberately omits secret parsing details.
547	    }
548	  }
549	  if (topology.mode === "single-cell" && Object.keys(keys).length === 0) {
550	    keys = {
551	      [topology.routing.activeKeyId]: base.secrets.authfn ?? base.secrets.oauth,
552	    };
553	  }
554	  const expected = new Set(topology.routing.verificationKeyIds);
555	  const received = new Set(Object.keys(keys));
556	  if (
557	    expected.size !== received.size ||
558	    [...expected].some((keyId) => !received.has(keyId)) ||
559	    !keys[topology.routing.activeKeyId]
560	  ) {
560	  ) {
561	    throw new ConfigError(
562	      "PRODUCTION_BINDING_MISSING",
563	      "The workspace routing keyring is unavailable",
564	      ["WORKSPACE_ROUTING_KEYS"],
565	    );
566	  }
567	  if (
568	    topology.mode === "multi-cell" &&
569	    Object.values(keys).some(
570	      (secret) => secret === base.secrets.authfn || secret === base.secrets.oauth,
571	    )
572	  ) {
573	    throw new ConfigError(
574	      "CONFIG_INVALID",
575	      "Workspace routing keys must be independent from authentication secrets",
576	      ["WORKSPACE_ROUTING_KEYS"],
577	    );
578	  }
579	  return {
580	    activeKeyId: topology.routing.activeKeyId,
581	    keys,
582	    audience: topology.routing.assertionAudience,
583	    ttlMs: topology.routing.assertionTtlSeconds * 1_000,
584	  };
585	}
