587	function attachTopology(
588	  base: RuntimeBaseConfig,
589	  bindings: RuntimeBindings,
590	): RuntimeConfig {
591	  const explicit = typeof bindings.SKILLPLANE_TOPOLOGY === "string";
592	  const topology = explicit
593	    ? parseTopologyManifest(bindings.SKILLPLANE_TOPOLOGY, {
594	        production: base.environment === "production",
595	      })
596	    : createSingleCellTopology({
597	        appAuthority: base.oauth.issuer,
598	        mcpResource: base.oauth.resource,
599	        controlDatabaseBinding: "HYPERDRIVE",
600	        publicObjectStorageBinding: "SKILL_BUNDLES",
601	        regionId: "legacy",
602	        regionalDatabaseBinding: "CELL_HYPERDRIVE",
603	        regionalObjectStorageBinding: "CELL_SKILL_BUNDLES",
604	      });
605	  const role = explicit ? bindings.SKILLPLANE_ROLE : "single";
606	  if (!role || !["single", "gateway", "control", "cell"].includes(role)) {
607	    throw new ConfigError("CONFIG_INVALID", "Deployment role is invalid", [
608	      "SKILLPLANE_ROLE",
609	    ]);
610	  }
611	  if (explicit && role === "single") {
612	    throw new ConfigError(
613	      "CONFIG_INVALID",
614	      "An explicit topology requires a gateway, control, or cell role",
615	      ["SKILLPLANE_ROLE"],
616	    );
617	  }
618	  const selectedRegion =
619	    role === "cell"
620	      ? topology.cells.find((cell) => cell.regionId === bindings.SKILLPLANE_REGION_ID)
621	      : undefined;
622	  if (role === "cell" && !selectedRegion) {
623	    throw new ConfigError(
624	      "CONFIG_INVALID",
625	      "The regional cell is not declared by the topology",
626	      ["SKILLPLANE_REGION_ID"],
627	    );
628	  }
629	  const controlDatabase = explicit
630	    ? databaseFromBinding(
631	        bindings[topology.controlPlane.databaseBinding],
632	        base.environment,
633	      )
634	    : base.database;
635	  const regionalDatabase = selectedRegion
636	    ? databaseFromBinding(bindings[selectedRegion.databaseBinding], base.environment)
637	    : role === "single"
638	      ? base.database
639	      : null;
640	  const publicObjectStorage = explicit
641	    ? bindings[topology.controlPlane.publicObjectStorageBinding]
642	    : base.objectStorage;
643	  const regionalObjectStorage = selectedRegion
644	    ? bindings[selectedRegion.objectStorageBinding]
645	    : role === "single"
646	      ? base.objectStorage
647	      : null;
648	  const missing: string[] = [];
649	  if (!controlDatabase) missing.push(topology.controlPlane.databaseBinding);
650	  if (role === "cell" && !regionalDatabase) {
651	    missing.push(selectedRegion?.databaseBinding ?? "SKILLPLANE_REGION_ID");
652	  }
653	  if (
654	    ["single", "gateway", "control"].includes(role) &&
655	    !isObjectStorageBinding(publicObjectStorage)
656	  ) {
657	    missing.push(topology.controlPlane.publicObjectStorageBinding);
658	  }
659	  if (role === "cell" && !isObjectStorageBinding(regionalObjectStorage)) {
660	    missing.push(selectedRegion?.objectStorageBinding ?? "SKILLPLANE_REGION_ID");
661	  }
662	  if (missing.length > 0 || !controlDatabase) {
663	    throw new ConfigError(
664	      "PRODUCTION_BINDING_MISSING",
665	      "Topology database or object-storage bindings are unavailable",
666	      [...new Set(missing)].sort(),
667	    );
668	  }
669	  const publicStorage = isObjectStorageBinding(publicObjectStorage)
670	    ? publicObjectStorage
671	    : null;
672	  const regionalStorage = isObjectStorageBinding(regionalObjectStorage)
673	    ? regionalObjectStorage
674	    : null;
675	  return {
676	    ...base,
677	    database: regionalDatabase ?? controlDatabase,
678	    objectStorage: regionalStorage ?? publicStorage ?? base.objectStorage,
679	    deployment: {
680	      role: role as RuntimeConfig["deployment"]["role"],
681	      regionId: selectedRegion?.regionId ?? (role === "single" ? "legacy" : null),
682	      topology,
683	    },
684	    controlDatabase,
685	    regionalDatabase,
686	    publicObjectStorage: publicStorage,
687	    regionalObjectStorage: regionalStorage,
688	    routing: routingKeys(bindings, base, topology),
689	  };
690	}
