722	  if (!isObjectStorageBinding(baseObjectStorage)) {
723	    throw new ConfigError(
724	      "PRODUCTION_BINDING_MISSING",
725	      "Object storage binding is unavailable",
726	      [baseStorageBinding ?? "SKILLPLANE_REGION_ID"],
727	    );
728	  }
729	
730	  if (environment === "local") {
731	    const explicitDatabase = explicitTopology
732	      ? databaseFromBinding(
733	          bindings[explicitTopology.controlPlane.databaseBinding],
734	          environment,
735	        )
736	      : null;
737	    const legacyDatabase = databaseFromBinding(bindings.DATABASE_URL, environment);
738	    const baseDatabase = explicitDatabase ?? legacyDatabase;
739	    if (!baseDatabase) {
740	      throw new ConfigError(
741	        "CONFIG_INVALID",
742	        "Local Postgres configuration is invalid",
743	        [
744	          explicitTopology
745	            ? explicitTopology.controlPlane.databaseBinding
746	            : "DATABASE_URL",
747	        ],
748	      );
749	    }
750	
751	    const authentication = oauthOnly
752	      ? { auth: null, email: null }
753	      : parseAuthConfiguration(bindings, environment);
