755	      {
756	        environment,
757	        database: baseDatabase,
758	        objectStorage: baseObjectStorage,
759	        email: authentication.email,
760	        auth: authentication.auth,
761	        oauth,
762	        secrets: {
763	          authfn: authentication.auth?.rateLimitPepper ?? null,
764	          turnstile: authentication.auth?.turnstile.secretKey ?? null,
765	          oauth: oauth.tokenPepper,
766	        },
767	        diagnostics: {
768	          environment,
769	          database: "direct-postgres",
770	          objectStorage: "r2",
771	          email: oauthOnly
772	            ? "not-required-oauth-only"
773	            : authentication.email
774	              ? "cloudflare-email"
775	              : "not-required-local",
776	          secretPresence: {
777	            authfn: Boolean(authentication.auth),
778	            turnstile: Boolean(authentication.auth),
779	            oauth: true,
780	          },
781	        },
782	      },
783	      bindings,
784	    );
785	  }
786	
787	  const productionDatabaseBinding = explicitTopology
788	    ? explicitTopology.controlPlane.databaseBinding
789	    : "HYPERDRIVE";
790	  const productionDatabase = databaseFromBinding(
791	    bindings[productionDatabaseBinding],
792	    environment,
793	  );
794	  const missing: string[] = [];
795	  if (!productionDatabase) missing.push(productionDatabaseBinding);
796	  if (missing.length > 0) {
797	    throw new ConfigError(
798	      "PRODUCTION_BINDING_MISSING",
799	      "Required production bindings are unavailable",
800	      missing.sort(),
801	    );
802	  }
803	
804	  if (bindings.DATABASE_URL !== undefined) {
