    84	export function classifyApiScope(request: Request): ApiScope {
    85	  const url = new URL(request.url);
    86	  const path = url.pathname;
    87	  if (path.startsWith("/datafn/")) {
    88	    return {
    89	      kind: "workspace",
    90	      workspaceId: segment(
    91	        request.headers.get("x-skillplane-workspace-id") ?? undefined,
    92	      ),
    93	    };
    94	  }
    95	  let match = /^\/api\/v1\/workspaces\/([^/]+)\/skills(?:\/|$)/u.exec(path);
    96	  if (match) return { kind: "workspace", workspaceId: segment(match[1]) };
    97	  match = /^\/api\/v1\/(?:audit|analytics)\/workspaces\/([^/]+)(?:\/|$)/u.exec(path);
    98	  if (match) return { kind: "workspace", workspaceId: segment(match[1]) };
    99	  if (path === "/api/v1/skills/search") {
   100	    const workspaceId = url.searchParams.get("workspaceId");
   101	    return workspaceId
   102	      ? { kind: "workspace", workspaceId: segment(workspaceId) }
