   104	  }
   105	  if (
   106	    path.startsWith("/api/v1/skills/public") ||
   107	    path.startsWith("/api/v1/stats/public")
   108	  ) {
   109	    return { kind: "global" };
   110	  }
   111	  match = /^\/api\/v1\/skills\/([^/]+)(?:\/|$)/u.exec(path);
   112	  if (match) {
   113	    return { kind: "resource", resourceType: "skill", resourceId: segment(match[1]) };
   114	  }
   115	  match = /^\/api\/v1\/contexts\/([^/]+)(?:\/|$)/u.exec(path);
   116	  if (match) {
   117	    return { kind: "resource", resourceType: "context", resourceId: segment(match[1]) };
   118	  }
