   252	export async function closeApiServices(services: ApiServices): Promise<void> {
   253	  let firstError: unknown;
   254	  const close = async (operation: () => Promise<void>): Promise<void> => {
   255	    try {
   256	      await operation();
   257	    } catch (error) {
   258	      firstError ??= error;
   259	    }
   260	  };
   261	
   262	  await close(() => services.datafn.close());
   263	  const email = services.email;
   264	  if (email) {
   265	    await close(() => email.close());
   266	  }
   267	  if (services.database !== services.controlDatabase) {
   268	    await close(() => services.database.close());
   269	  }
   270	  await close(() => services.controlDatabase.close());
   271	
   272	  if (firstError instanceof Error) throw firstError;
   273	  if (firstError !== undefined) {
   274	    throw new Error("API service cleanup failed", { cause: firstError });
   275	  }
   276	}
