 69	function record(value: unknown): Record<string, unknown> | null {
 70	  return value && typeof value === "object" && !Array.isArray(value)
 71	    ? (value as Record<string, unknown>)
 72	    : null;
 73	}
 74	
 75	function identifier(value: unknown): string | null {
 76	  return typeof value === "string" && value.length > 0 && value.length <= 200
 77	    ? value
 78	    : null;
 79	}
