170	    const result = await services.controlDatabase.pool.query<{ id: string }>(
171	      "SELECT id FROM workspaces WHERE slug = $1 LIMIT 1",
172	      [slug],
173	    );
174	    if (result.rows[0]) return result.rows[0].id;
175	  }
176	  throw new McpRoutingError(
177	    404,
178	    "WORKSPACE_ROUTE_NOT_FOUND",
179	    "The workspace route was not found",
180	  );
181	}
