240	        return await input.local.fetch(request, bindings);
241	      }
242	      const scope = classifyApiScope(request);
243	      if (runtime.deployment.role === "control") {
244	        return scope.kind === "global"
245	          ? await input.local.fetch(request, bindings)
246	          : new ApiRoutingError(
247	              404,
248	              "CONTROL_ROUTE_NOT_FOUND",
249	              "The control-plane route was not found",
250	            ).response();
251	      }
252	      if (runtime.deployment.role === "gateway") {
253	        if (scope.kind === "global") {
254	          return await input.local.fetch(request, bindings);
255	        }
256	        const services = await input.services(bindings);
257	        try {
258	          const workspaceId = await resolveWorkspace(request, scope, services);
259	          const assertions = createWorkspaceRoutingAssertions({
