264	            directory: createPostgresWorkspacePlacementDirectory(
265	              services.controlDatabase.pool,
266	            ),
267	            resolveAuthorizedWorkspace: () => Promise.resolve(workspaceId),
268	            cells: {
269	              resolve: ({ regionId }) => {
270	                const cell = runtime.deployment.topology.cells.find(
271	                  (candidate) => candidate.regionId === regionId,
272	                );
273	                const binding = cell
274	                  ? serviceBinding(bindings[cell.appServiceBinding])
275	                  : null;
276	                if (!cell || !binding) throw new Error("regional app unavailable");
277	                return {
278	                  regionId,
279	                  fetch: (forwarded) => Promise.resolve(binding.fetch(forwarded)),
