122	export async function classifyMcpScope(request: Request): Promise<McpScope> {
123	  if (request.method !== "POST" || new URL(request.url).pathname !== "/mcp") {
124	    return { kind: "global" };
125	  }
126	  let body: unknown;
127	  try {
128	    body = await request.clone().json();
129	  } catch {
130	    return { kind: "global" };
131	  }
132	  const scopes = (Array.isArray(body) ? body : [body]).map(scopeForMessage);
133	  const workspaceScopes = scopes.filter(
134	    (scope): scope is Exclude<McpScope, { readonly kind: "global" }> =>
135	      scope.kind !== "global",
136	  );
137	  if (workspaceScopes.length === 0) return { kind: "global" };
138	  if (workspaceScopes.length !== scopes.length) {
139	    throw new McpRoutingError(
140	      400,
141	      "WORKSPACE_BATCH_INVALID",
142	      "An MCP batch cannot mix global and workspace operations",
143	    );
144	  }
145	  const first = JSON.stringify(workspaceScopes[0]);
146	  if (workspaceScopes.some((scope) => JSON.stringify(scope) !== first)) {
147	    throw new McpRoutingError(
148	      400,
149	      "WORKSPACE_BATCH_INVALID",
150	      "An MCP batch cannot span multiple workspaces",
151	    );
152	  }
153	  const firstScope = workspaceScopes[0];
154	  if (!firstScope) return { kind: "global" };
155	  return firstScope;
156	}
