 81	function scopeForMessage(message: unknown): McpScope {
 82	  const root = record(message);
 83	  const params = record(root?.params);
 84	  if (root?.method !== "tools/call" || typeof params?.name !== "string") {
 85	    return { kind: "global" };
 86	  }
 87	  if (params.name === "workspaces_list") return { kind: "global" };
 88	  const arguments_ = record(params.arguments);
 89	  const allowPublic =
 90	    params.name === "skill_asset_retrieve" ||
 91	    params.name === "skill_versions_list" ||
 92	    (params.name === "skill_retrieve" && !record(arguments_?.context));
 93	  const workspace = record(arguments_?.workspace);
 94	  const workspaceId = identifier(workspace?.id) ?? identifier(arguments_?.workspaceId);
 95	  if (workspaceId) {
 96	    return { kind: "workspace-id", value: workspaceId, allowPublic: false };
 97	  }
 98	  const workspaceSlug = identifier(workspace?.slug);
 99	  if (workspaceSlug) {
100	    return { kind: "workspace-slug", value: workspaceSlug, allowPublic: false };
101	  }
102	  const skill = record(arguments_?.skill);
103	  const skillId = identifier(skill?.id);
104	  if (skillId) return { kind: "skill-id", value: skillId, allowPublic };
105	  const skillWorkspaceSlug = identifier(skill?.workspaceSlug);
106	  const skillSlug = identifier(skill?.skillSlug);
107	  if (skillWorkspaceSlug && skillSlug) {
108	    return {
109	      kind: "skill-slug",
110	      workspaceSlug: skillWorkspaceSlug,
111	      skillSlug,
112	      allowPublic,
113	    };
114	  }
115	  throw new McpRoutingError(
116	    400,
117	    "WORKSPACE_ROUTE_INVALID",
118	    "The MCP tool call does not identify one workspace",
119	  );
120	}
