158	async function resolveWorkspaceId(
159	  scope: Exclude<McpScope, { readonly kind: "global" }>,
160	  services: ApiServices,
161	): Promise<string> {
162	  if (scope.kind === "workspace-id") return scope.value;
163	  if (scope.kind === "skill-id") {
164	    const route = await createPostgresResourceRoutingDirectory(
165	      services.controlDatabase.pool,
166	    ).resolve("skill", scope.value);
167	    if (route) return route.workspaceId;
168	  } else {
169	    const slug = scope.kind === "workspace-slug" ? scope.value : scope.workspaceSlug;
170	    const result = await services.controlDatabase.pool.query<{ id: string }>(
171	      "SELECT id FROM workspaces WHERE slug = $1 LIMIT 1",
172	      [slug],
173	    );
174	    if (result.rows[0]) return result.rows[0].id;
175	  }
176	  throw new McpRoutingError(
177	    404,
178	    "WORKSPACE_ROUTE_NOT_FOUND",
179	    "The workspace route was not found",
180	  );
181	}
