 51	class McpRoutingError extends Error {
 52	  readonly status: number;
 53	  readonly code: string;
 54	
 55	  constructor(status: number, code: string, message: string) {
 56	    super(message);
 57	    this.status = status;
 58	    this.code = code;
 59	  }
 60	
 61	  response(): Response {
 62	    return Response.json(
 63	      { error: this.code, error_description: this.message },
 64	      { status: this.status, headers: { "cache-control": "no-store" } },
 65	    );
 66	  }
 67	}
