183	async function authorizeWorkspace(
184	  identity: McpIdentity,
185	  scope: Exclude<McpScope, { readonly kind: "global" }>,
186	  workspaceId: string,
187	  services: ApiServices,
188	): Promise<void> {
189	  const publicProjectionExists = async (): Promise<boolean> => {
190	    if (!scope.allowPublic) return false;
191	    const result = await services.controlDatabase.pool.query(
192	      scope.kind === "skill-id"
193	        ? `SELECT 1 FROM public_skill_projections
194	             WHERE workspace_id = $1 AND skill_id = $2 AND state = 'published'
195	             LIMIT 1`
196	        : `SELECT 1 FROM public_skill_projections
197	             WHERE workspace_id = $1 AND workspace_slug = $2
198	               AND skill_slug = $3 AND state = 'published'
199	             LIMIT 1`,
200	      scope.kind === "skill-id"
201	        ? [workspaceId, scope.value]
202	        : [workspaceId, scope.workspaceSlug, scope.skillSlug],
203	    );
204	    return Boolean(result.rows[0]);
205	  };
206	  if (identity.kind === "service") {
207	    if (identity.workspaceId !== workspaceId) {
208	      if (await publicProjectionExists()) return;
209	      throw new McpRoutingError(
210	        403,
211	        "WORKSPACE_ACCESS_DENIED",
212	        "Workspace access is denied",
213	      );
214	    }
215	    return;
216	  }
217	  const membership = await services.controlDatabase.pool.query<{ present: number }>(
218	    `SELECT 1 AS present
219	       FROM workspace_memberships
220	      WHERE workspace_id = $1 AND user_id = $2
221	      LIMIT 1`,
222	    [workspaceId, identity.userId],
223	  );
224	  if (!membership.rows[0]) {
225	    if (await publicProjectionExists()) return;
226	    throw new McpRoutingError(
227	      403,
228	      "WORKSPACE_ACCESS_DENIED",
229	      "Workspace access is denied",
230	    );
231	  }
232	}
