243	function cleanPublicRequest(request: Request): Request {
244	  const headers = new Headers(request.headers);
245	  headers.delete("x-skillplane-routed-workspace-id");
246	  headers.delete("x-skillplane-routing-region");
247	  headers.delete("x-skillplane-routing-epoch");
248	  headers.delete("x-datafn-routing-assertion");
249	  return new Request(request, { headers });
