252	/** Routes authenticated workspace tool calls to a private regional MCP cell. */
253	export function createRoutedMcpApplication<Context>(input: {
254	  readonly local: McpApplication<Context>;
255	  readonly services: ApiServiceProvider;
256	}): McpApplication<Context> {
257	  return {
258	    async fetch(incoming, bindings, context) {
259	      const runtime = parseRuntimeConfig(bindings, { authentication: "oauth-only" });
260	      const request =
261	        runtime.deployment.role === "cell" ? incoming : cleanPublicRequest(incoming);
262	      if (runtime.deployment.role === "single") {
263	        return await input.local.fetch(request, bindings, context);
264	      }
265	      try {
266	        const scope = await classifyMcpScope(request);
267	        if (runtime.deployment.role === "control") {
268	          return scope.kind === "global"
269	            ? await input.local.fetch(request, bindings, context)
270	            : new McpRoutingError(
271	                404,
272	                "CONTROL_ROUTE_NOT_FOUND",
273	                "The control-plane MCP route was not found",
274	              ).response();
275	        }
276	        if (runtime.deployment.role === "gateway") {
277	          if (scope.kind === "global") {
278	            return await input.local.fetch(request, bindings, context);
279	          }
280	          const services = await input.services(bindings);
281	          try {
282	            const identity = await authenticateMcpRequest(request, services);
283	            const workspaceId = await resolveWorkspaceId(scope, services);
284	            await authorizeWorkspace(identity, scope, workspaceId, services);
285	            const assertions = createWorkspaceRoutingAssertions({
286	              activeKeyId: runtime.routing.activeKeyId,
287	              keys: runtime.routing.keys,
288	            });
289	            return await createWorkspaceGateway({
290	              directory: createPostgresWorkspacePlacementDirectory(
291	                services.controlDatabase.pool,
292	              ),
293	              resolveAuthorizedWorkspace: () => Promise.resolve(workspaceId),
294	              cells: {
295	                resolve: ({ regionId }) => {
296	                  const cell = runtime.deployment.topology.cells.find(
297	                    (candidate) => candidate.regionId === regionId,
298	                  );
299	                  const binding = cell
300	                    ? serviceBinding(bindings[cell.mcpServiceBinding])
301	                    : null;
302	                  if (!cell || !binding) throw new Error("regional MCP unavailable");
303	                  return {
304	                    regionId,
305	                    fetch: (forwarded) => Promise.resolve(binding.fetch(forwarded)),
306	                  };
307	                },
308	              },
309	              signer: assertions,
310	              assertionAudience: runtime.routing.audience,
311	              assertionTtlMs: runtime.routing.ttlMs,
312	              onEvent: (event) => logWorkspaceRoutingEvent("mcp", event),
313	            }).handle(request);
314	          } finally {
315	            await input.services.release?.(services);
316	          }
317	        }
318	        if (scope.kind === "global" || !runtime.deployment.regionId) {
319	          throw new McpRoutingError(
320	            404,
321	            "REGIONAL_ROUTE_NOT_FOUND",
322	            "The regional MCP route was not found",
323	          );
324	        }
325	        const workspaceId = request.headers.get("x-skillplane-routed-workspace-id");
326	        if (!workspaceId) {
327	          throw new McpRoutingError(
328	            401,
329	            "WORKSPACE_ROUTING_ASSERTION_REQUIRED",
330	            "A trusted workspace routing assertion is required",
331	          );
332	        }
333	        const services = await input.services(bindings);
334	        try {
335	          const assertions = createWorkspaceRoutingAssertions({
336	            activeKeyId: runtime.routing.activeKeyId,
337	            keys: runtime.routing.keys,
338	          });
339	          const authorized = await createRegionalWorkspaceGuard({
340	            regionId: runtime.deployment.regionId,
341	            directory: createPostgresWorkspacePlacementDirectory(
342	              services.controlDatabase.pool,
343	            ),
344	            verifier: assertions,
345	            replayStore: createPostgresRoutingReplayStore(
346	              services.controlDatabase.pool,
347	            ),
348	            assertionAudience: runtime.routing.audience,
349	            onEvent: (event) => logWorkspaceRoutingEvent("mcp", event),
350	          }).authorize(request, workspaceId);
351	          return await input.local.fetch(authorized.request, bindings, context);
352	        } finally {
353	          await input.services.release?.(services);
354	        }
355	      } catch (error) {
356	        if (error instanceof McpAuthenticationError) {
357	          return mcpAuthenticationResponse(null, error);
358	        }
359	        if (error instanceof McpRoutingError) return error.response();
360	        if (
361	          error &&
362	          typeof error === "object" &&
363	          "toResponse" in error &&
364	          typeof (error as { toResponse?: unknown }).toResponse === "function"
365	        ) {
366	          return (error as { toResponse(): Response }).toResponse();
367	        }
368	        return new McpRoutingError(
369	          503,
370	          "WORKSPACE_ROUTING_UNAVAILABLE",
371	          "Workspace routing is temporarily unavailable",
372	        ).response();
373	      }
374	    },
375	  };
376	}
