   400	  request: Request,
   401	  token: string,
   402	  services: ApiServices,
   403	  identity: McpIdentity,
   404	  audit: McpAuditWriter,
   405	  now: () => Date,
   406	): Promise<Response> {
   407	  const startedAt = performance.now();
   408	  let scope: ToolAuditScope = {};
   409	  let grant: Awaited<ReturnType<typeof verifyDownloadGrant>> | undefined;
   410	  try {
   411	    grant = await verifyDownloadGrant(token, services.auth.oauth.tokenPepper, now());
   412	    scope = {
   413	      workspaceId: grant.workspaceId,
   414	      resourceType: "skill_version",
   415	      resourceId: grant.versionId,
   416	      skillId: grant.skillId,
   417	      versionId: grant.versionId,
   418	      versionDigest: grant.bundleDigest,
