   428	    const execution: ToolExecution = {
   429	      requestId: grant.requestId,
   430	      scope,
   431	      setScope(values) {
   432	        scope = { ...scope, ...values };
   433	      },
   434	    };
   435	    const skill = await resolveSkill(
   436	      runtime,
   437	      execution,
   438	      { id: grant.skillId },
   439	      { action: "skills:read", allowPublic: true },
   440	    );
   441	    const version = await resolveVersion(runtime, execution, skill, {
   442	      selector: "versionId",
   443	      versionId: grant.versionId,
   444	    });
   445	    if (
   446	      skill.workspaceId !== grant.workspaceId ||
   447	      version.digest !== grant.bundleDigest
   448	    ) {
   449	      throw new McpToolError(
   450	        "AUTH_INVALID",
   451	        "The download grant no longer matches the resource",
   452	        { status: 401 },
   453	      );
   454	    }
   455	    const path = normalizeBundlePath(grant.path);
   456	    const bundle = await loadExactCanonicalBundle(runtime, version);
