   485	      status: 200,
   486	      headers: {
   487	        "cache-control": "private, no-store",
   488	        "content-disposition": `attachment; filename*=UTF-8''${encodeURIComponent(
   489	          filename,
   490	        )}`,
   491	        "content-security-policy": "sandbox; default-src 'none'",
   492	        "content-type": descriptor.mediaType,
   493	        "cross-origin-resource-policy": "same-origin",
   494	        pragma: "no-cache",
   495	        "x-content-type-options": "nosniff",
   496	      },
   497	    });
