   503	          workspaceId: scope.workspaceId,
   504	          requestId: grant.requestId,
   505	          tool: "skill_asset_download",
   506	          outcome:
   507	            error.status === 401 || error.status === 403 || error.status === 404
   508	              ? "denied"
   509	              : "error",
   510	          identity,
   511	          caller: grant.caller,
   512	          ...(scope.resourceType ? { resourceType: scope.resourceType } : {}),
   513	          ...(scope.resourceId ? { resourceId: scope.resourceId } : {}),
   514	          ...(scope.skillId ? { skillId: scope.skillId } : {}),
   515	          ...(scope.versionId ? { versionId: scope.versionId } : {}),
   516	          ...(scope.versionDigest ? { versionDigest: scope.versionDigest } : {}),
   517	          errorCode: error.code,
   518	          latencyMs: performance.now() - startedAt,
   519	          countMetric: false,
   520	        });
   521	      } catch (auditError) {
   522	        error = mapMcpToolError(auditError);
   523	      }
   524	    }
   525	    return jsonError(error.status, error.code, error.message);
   526	  }
