    13	export async function writeControlPlaneAudit(
    14	  sql: SqlWriter,
    15	  event: {
    16	    readonly [field: string]: unknown;
    17	    readonly workspaceId?: string | null;
    18	    readonly eventType: string;
    19	    readonly action: string;
    20	    readonly outcome: string;
    21	    readonly actorType: string;
