    81	    requestId: event.requestId,
    82	    ...(event.resourceType ? { resourceType: event.resourceType } : {}),
    83	    ...(event.resourceId ? { resourceId: event.resourceId } : {}),
    84	    ...(event.metadata ? { metadata: event.metadata } : {}),
    85	  });
