    11	export function enforceCookieCsrf(
    12	  request: Request,
    13	  hasSession: boolean,
    14	  hasServicePrincipal: boolean,
    15	): void {
    16	  const url = new URL(request.url);
    17	  if (
    18	    !hasSession ||
    19	    hasServicePrincipal ||
    20	    SAFE_METHODS.has(request.method) ||
    21	    !url.pathname.startsWith("/api/v1/")
    22	  ) {
    23	    return;
    24	  }
    25	  const cookie = request.headers.get("cookie") ?? "";
    26	  const bearerWithoutSessionCookie =
    27	    request.headers.get("authorization")?.startsWith("Bearer ") === true &&
    28	    !cookie
    29	      .split(";")
    30	      .some((entry) => entry.trim().startsWith(`${AUTH_SESSION_COOKIE}=`));
    31	  if (bearerWithoutSessionCookie) return;
    32	  const cookieToken = readCsrfToken(request.headers.get("cookie"));
    33	  const headerToken = request.headers.get(AUTH_CSRF_HEADER);
    34	  if (!cookieToken || !headerToken || cookieToken !== headerToken) {
    35	    throw new DomainError(
    36	      "AUTH_CSRF_INVALID",
    37	      "The request could not be verified",
    38	      403,
    39	    );
    40	  }
    41	}
