   109	export async function readBundleUpload(context: Context<ApiEnvironment>): Promise<{
   110	  readonly archiveBytes: Uint8Array;
   111	  readonly fields: Readonly<Record<string, unknown>>;
   112	}> {
   113	  const contentLength = Number(context.req.header("content-length"));
   114	  const mediaType = context.req.header("content-type")?.split(";", 1)[0]?.trim();
   115	  if (mediaType === "application/zip") {
   116	    if (Number.isFinite(contentLength) && contentLength > MAX_ARCHIVE_BYTES) {
   117	      throw new DomainError(
   118	        "SKILL_BUNDLE_TOO_LARGE",
   119	        "The compressed skill bundle exceeds 10 MiB",
   120	        400,
   121	      );
   122	    }
   123	    const archiveBytes = new Uint8Array(await context.req.arrayBuffer());
   124	    if (archiveBytes.byteLength === 0 || archiveBytes.byteLength > MAX_ARCHIVE_BYTES) {
   125	      throw new DomainError(
   126	        archiveBytes.byteLength === 0
   127	          ? "SKILL_BUNDLE_INVALID"
   128	          : "SKILL_BUNDLE_TOO_LARGE",
   129	        archiveBytes.byteLength === 0
   130	          ? "A ZIP skill bundle is required"
   131	          : "The compressed skill bundle exceeds 10 MiB",
   132	        400,
   133	      );
   134	    }
   135	    return {
   136	      archiveBytes,
   137	      fields: {
   138	        visibility: context.req.query("visibility"),
   139	        baseVersionId: context.req.header("x-skillplane-base-version-id"),
   140	        proposedBump: context.req.header("x-skillplane-proposed-bump"),
   141	        changeSummary: context.req.header("x-skillplane-change-summary"),
   142	      },
   143	    };
   144	  }
   145	  if (mediaType !== "application/json") {
   146	    throw new DomainError(
   147	      "VALIDATION_FAILED",
   148	      "Use application/zip or application/json with bundleBase64",
   149	      400,
   150	      { field: "content-type" },
   151	    );
   152	  }
   153	  if (Number.isFinite(contentLength) && contentLength > MAX_JSON_UPLOAD_BYTES) {
   154	    throw new DomainError(
   155	      "SKILL_BUNDLE_TOO_LARGE",
   156	      "The encoded skill bundle exceeds the upload limit",
   157	      400,
   158	    );
   159	  }
   160	  const fields = await readJsonObject(context);
   161	  return { archiveBytes: decodeBase64(fields.bundleBase64), fields };
   162	}
