   113	  const contentLength = Number(context.req.header("content-length"));
   114	  const mediaType = context.req.header("content-type")?.split(";", 1)[0]?.trim();
   115	  if (mediaType === "application/zip") {
   116	    if (Number.isFinite(contentLength) && contentLength > MAX_ARCHIVE_BYTES) {
   117	      throw new DomainError(
   118	        "SKILL_BUNDLE_TOO_LARGE",
   119	        "The compressed skill bundle exceeds 10 MiB",
