    43	export function authenticationMiddleware(
    44	  getServices?: ApiServiceProvider,
    45	): MiddlewareHandler<ApiEnvironment> {
    46	  return async (context, next) => {
    47	    if (!getServices || context.req.path.startsWith("/api/v1/health/")) {
    48	      context.set("services", null);
    49	      context.set("session", null);
    50	      context.set("servicePrincipal", null);
    51	      await next();
    52	      return;
    53	    }
    54	    const services = await getServices(context.env);
    55	    try {
    56	      context.set("services", services);
    57	      const serviceAuthentication = await authenticateServicePrincipalRequest(
    58	        context.req.raw,
    59	        services,
    60	      );
    61	      const servicePrincipal = serviceAuthentication?.principal ?? null;
    62	      context.set("servicePrincipal", servicePrincipal);
    63	      const session = servicePrincipal
    64	        ? null
    65	        : await services.auth.provider.authenticate(context.req.raw);
    66	      context.set("session", session);
    67	      if (session) {
    68	        await ensurePersonalWorkspace(
    69	          services.controlDatabase.pool,
    70	          session,
    71	          selectInitialWorkspaceRegion(session.actorId, services.workspaceRegions),
    72	        );
    73	      }
    74	      enforceCookieCsrf(context.req.raw, Boolean(session), Boolean(servicePrincipal));
    75	      await next();
    76	    } finally {
    77	      try {
    78	        await getServices.release?.(services);
    79	      } catch {
    80	        console.error(
    81	          JSON.stringify({
    82	            component: "api",
    83	            event: "api.services.release.failed",
    84	          }),
    85	        );
    86	      }
    87	    }
    88	  };
    89	}
