    82	function decodeBase64(value: unknown): Uint8Array {
    83	  if (
    84	    typeof value !== "string" ||
    85	    value.length === 0 ||
    86	    value.length > MAX_JSON_UPLOAD_BYTES ||
    87	    value.length % 4 !== 0 ||
