    90	    throw new DomainError(
    91	      "VALIDATION_FAILED",
    92	      "bundleBase64 must be valid base64 within the upload limit",
    93	      400,
    94	      { field: "bundleBase64" },
    95	    );
    96	  }
    97	  const binary = atob(value);
    98	  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
    99	  if (bytes.byteLength > MAX_ARCHIVE_BYTES) {
   100	    throw new DomainError(
   101	      "SKILL_BUNDLE_TOO_LARGE",
   102	      "The compressed skill bundle exceeds 10 MiB",
   103	      400,
   104	    );
   105	  }
   106	  return bytes;
   107	}
