   273	export function parseOptionalExpiry(value: unknown, now = new Date()): Date | null {
   274	  if (value === null || value === undefined || value === "") return null;
   275	  if (typeof value !== "string") {
   276	    throw new DomainError("VALIDATION_FAILED", "Expiry must be an ISO date", 400, {
   277	      field: "expiresAt",
