    70	  try {
    71	    identity = await services.auth.apiKeys.authenticate(token);
    72	  } catch (error) {
    73	    if (error instanceof AuthFnApiKeyRevokedError) {
    74	      throw new InvalidAuthenticationError();
    75	    }
    76	    throw error;
    77	  }
    78	  if (identity?.type !== "api-key" || identity.actorType !== "api-key") {
    79	    throw new InvalidAuthenticationError();
    80	  }
    81	  const result = await services.controlDatabase.pool.query<ServicePrincipalRow>(
    82	    `SELECT id, workspace_id, name, role, scopes, delegated_user_id,
    83	            expires_at, revoked_at, credential_version, authfn_api_key_id
    84	       FROM service_principals
    85	      WHERE authfn_api_key_id = $1
    86	      LIMIT 1`,
    87	    [identity.actorId],
    88	  );
    89	  const row = result.rows[0];
    90	  if (
    91	    !row ||
    92	    row.revoked_at ||
    93	    row.authfn_api_key_id !== identity.actorId ||
