   102	      WHERE id = $1
   103	        AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')`,
   104	    [row.id],
   105	  );
   106	  return {
   107	    principal,
   108	    credentialId: identity.actorId,
   109	    credentialKind: "service_principal",
   110	  };
   111	}
