    37	  if (Array.isArray(payload)) {
    38	    for (const item of payload) requestedResources(item, found);
    39	    return found;
    40	  }
    41	  const record = payload as Record<string, unknown>;
    42	  if (typeof record.resource === "string") {
    43	    found.add(record.resource);
    44	  }
    45	  if (Array.isArray(record.resources)) {
    46	    for (const resource of record.resources) {
    47	      if (typeof resource === "string") found.add(resource);
    48	    }
    49	  }
    50	  for (const value of Object.values(record)) {
    51	    if (typeof value === "object") requestedResources(value, found);
    52	  }
    53	  return found;
    54	}
