     1	import {
     2	  AuthenticationRequiredError,
     3	  DomainError,
     4	  WorkspaceAccessError,
     5	  authorize,
     6	} from "@skillplane/domain";
     7	import { writeAuditEvent } from "@skillplane/observability";
     8	import type { WorkspaceAction } from "@skillplane/domain";
     9	import type { MiddlewareHandler } from "hono";
    10	import { routePath } from "hono/route";
    11	import type { ApiEnvironment } from "../context.js";
    12	import { resolveWorkspaceRequestContext } from "./context.js";
    13	
    14	export function requiredAction(path: string, method: string): WorkspaceAction | null {
    15	  const read = ["GET", "HEAD", "OPTIONS"].includes(method);
    16	  if (/^\/api\/v1\/skills\/[^/]+\/amendments(?:\/|$)/u.test(path)) {
    17	    return read ? "skills:read" : "skills:amend";
    18	  }
    19	  if (/^\/api\/v1\/skills\/[^/]+\/amendment-policy(?:\/|$)/u.test(path)) {
    20	    return read ? "skills:read" : "skills:publish";
    21	  }
    22	  if (/^\/api\/v1\/skills\/[^/]+\/reviews\/[^/]+\/(?:approve|reject)$/u.test(path)) {
    23	    return "skills:publish";
    24	  }
    25	  if (/^\/api\/v1\/skills\/[^/]+\/candidates(?:\/|$)/u.test(path)) {
    26	    return "skills:read";
    27	  }
    28	  if (
    29	    path.startsWith("/api/v1/contexts") ||
    30	    path.startsWith("/api/v1/context-notes") ||
    31	    /^\/api\/v1\/skills\/[^/]+\/contexts(?:\/|$)/u.test(path)
    32	  ) {
    33	    return read ? "contexts:read" : "contexts:write";
    34	  }
    35	  if (path.startsWith("/api/v1/skills")) {
    36	    return read ? "skills:read" : "skills:write";
    37	  }
    38	  if (path.startsWith("/api/v1/analytics")) return "analytics:read";
    39	  if (path.startsWith("/api/v1/audit")) return "audit:read";
    40	  return null;
    41	}
    42	
    43	export function authorizationMiddleware(): MiddlewareHandler<ApiEnvironment> {
    44	  return async (context, next) => {
    45	    context.set("principal", null);
    46	    if (context.req.path.startsWith("/api/v1/workspaces") && !context.get("session")) {
    47	      throw new AuthenticationRequiredError();
    48	    }
    49	    if (context.req.path.startsWith("/datafn/")) {
    50	      const principal = await resolveWorkspaceRequestContext(context);
    51	      context.set("principal", principal);
    52	      await next();
    53	      return;
    54	    }
    55	    const action = requiredAction(context.req.path, context.req.method);
    56	    if (action) {
    57	      const explicitPublicSkillRead =
    58	        action === "skills:read" &&
    59	        context.req.path.startsWith("/api/v1/skills/public/");
    60	      if (explicitPublicSkillRead) {
    61	        await next();
    62	        return;
    63	      }
    64	      const servicePrincipal = context.get("servicePrincipal");
    65	      const requestedWorkspace = context.req.header("x-skillplane-workspace-id");
    66	      const publicSkillRead =
    67	        action === "skills:read" && !servicePrincipal && !requestedWorkspace;
    68	      if (publicSkillRead) {
    69	        await next();
    70	        return;
    71	      }
    72	      if (
    73	        servicePrincipal &&
    74	        requestedWorkspace &&
    75	        requestedWorkspace !== servicePrincipal.workspaceId
    76	      ) {
    77	        throw new WorkspaceAccessError();
    78	      }
    79	      const principal =
    80	        servicePrincipal ?? (await resolveWorkspaceRequestContext(context));
    81	      try {
    82	        authorize(principal, action);
    83	      } catch (error) {
    84	        const services = context.get("services");
    85	        if (!services) throw error;
    86	        try {
    87	          await writeAuditEvent(services.database.pool, {
    88	            workspaceId: principal.workspaceId,
    89	            eventType: "authorization.denied",
    90	            action,
    91	            outcome: "denied",
    92	            actorType: principal.kind === "user" ? "user" : "service_principal",
    93	            actorId: principal.actorId,
    94	            userId:
    95	              principal.kind === "user"
    96	                ? principal.userId
    97	                : (principal.delegatedUserId ?? null),
    98	            requestId: context.get("requestId"),
    99	            resourceType: "workspace",
   100	            resourceId: principal.workspaceId,
   101	            channel: "app",
   102	            retentionClass: "permanent",
   103	            metadata: {
   104	              method: context.req.method,
   105	              requestedAction: action,
   106	              route: routePath(context) || "unmatched",
   107	            },
   108	          });
   109	        } catch {
   110	          throw new DomainError(
   111	            "AUDIT_WRITE_FAILED",
   112	            "The authorization decision could not be recorded",
   113	            503,
   114	          );
   115	        }
   116	        throw error;
   117	      }
   118	      context.set("principal", principal);
   119	    }
   120	    await next();
   121	  };
   122	}
     1	import { resolveUserPrincipal } from "@skillplane/db";
     2	import { AuthenticationRequiredError, type Principal } from "@skillplane/domain";
     3	import type { Context } from "hono";
     4	import type { ApiEnvironment } from "../context.js";
     5	
     6	export async function resolveWorkspaceRequestContext(
     7	  context: Context<ApiEnvironment>,
     8	): Promise<Principal> {
     9	  const services = context.get("services");
    10	  if (!services) {
    11	    throw new AuthenticationRequiredError();
    12	  }
    13	  return resolveUserPrincipal(
    14	    services.controlDatabase.pool,
    15	    context.get("session"),
    16	    context.req.header("x-skillplane-workspace-id"),
    17	  );
    18	}
