    13	async function enqueue(
    14	  services: ApiServices,
    15	  workspaceId: string,
    16	  eventType: "public_skill.published" | "public_skill.unpublished",
    17	  payload: Readonly<Record<string, unknown>>,
    18	  epoch: number,
    19	): Promise<void> {
    20	  const client = await services.database.pool.connect();
    21	  try {
    22	    await client.query("BEGIN");
