    26	         (id, workspace_id, event_type, payload, fencing_epoch, sequence)
    27	       SELECT $1, $2, $3, $4::jsonb, $5, COALESCE(MAX(sequence), 0) + 1
    28	         FROM regional_projection_outbox
    29	        WHERE workspace_id = $2`,
    30	      [
    31	        `regional-projection:${crypto.randomUUID()}`,
    32	        workspaceId,
    33	        eventType,
    34	        JSON.stringify(payload),
    35	        epoch,
    36	      ],
    37	    );
    38	    await client.query("COMMIT");
    39	  } catch (error) {
    40	    await client.query("ROLLBACK").catch(() => undefined);
    41	    throw error;
    42	  } finally {
