    13	async function enqueue(
    14	  services: ApiServices,
    15	  workspaceId: string,
    16	  eventType: "public_skill.published" | "public_skill.unpublished",
    17	  payload: Readonly<Record<string, unknown>>,
    18	  epoch: number,
    19	): Promise<void> {
    20	  const client = await services.database.pool.connect();
    21	  try {
    22	    await client.query("BEGIN");
    23	    await client.query("SELECT pg_advisory_xact_lock(hashtext($1))", [workspaceId]);
    24	    await client.query(
    25	      `INSERT INTO regional_projection_outbox
    26	         (id, workspace_id, event_type, payload, fencing_epoch, sequence)
    27	       SELECT $1, $2, $3, $4::jsonb, $5, COALESCE(MAX(sequence), 0) + 1
    28	         FROM regional_projection_outbox
    29	        WHERE workspace_id = $2`,
    30	      [
    31	        `regional-projection:${crypto.randomUUID()}`,
    32	        workspaceId,
    33	        eventType,
    34	        JSON.stringify(payload),
    35	        epoch,
    36	      ],
    37	    );
    38	    await client.query("COMMIT");
    39	  } catch (error) {
    40	    await client.query("ROLLBACK").catch(() => undefined);
    41	    throw error;
    42	  } finally {
    43	    client.release();
    44	  }
    45	}
