#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const filters = args.flatMap((argument, index) =>
  argument === "--filter" && args[index + 1] ? [args[index + 1]] : [],
);
const positional = args.slice(Math.max(0, args.indexOf("--") + 1));

const localRuntimeTests = spawnSync(
  process.execPath,
  [
    "--test",
    "scripts/lib/local-postgres-port.test.mjs",
    "scripts/lib/local-wrangler-config.test.mjs",
    "scripts/lib/local-worker-vars.test.mjs",
    "scripts/local-init.test.mjs",
    "scripts/development-deployment.test.mjs",
    "scripts/production-deployment.test.mjs",
    "scripts/migrate-production-origin.test.mjs",
    "scripts/development-entrypoints.test.mjs",
    "scripts/migrate-development.test.mjs",
    "scripts/configure-local-oauth.test.mjs",
    "scripts/test-local-oauth.test.mjs",
    "scripts/production-smoke.test.mjs",
    "scripts/production-deployment.test.mjs",
    "scripts/rollback.test.mjs",
    "scripts/topology-manifest.test.mjs",
    "scripts/topology-deployment.test.mjs",
  ],
  {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "inherit",
  },
);
if (localRuntimeTests.status !== 0) {
  process.exit(localRuntimeTests.status ?? 1);
}

if (filters.length === 1 && filters[0] === "app" && positional.includes("skills")) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/app",
      "exec",
      "vitest",
      "run",
      "tests/unit/skills.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/domain" &&
  positional.some((name) =>
    ["amendments", "learning-metadata", "policies"].includes(name),
  )
) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/domain",
      "exec",
      "vitest",
      "run",
      "src/amendments.test.ts",
      "src/learning-metadata.test.ts",
      "src/amendment-policy.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/domain" &&
  positional.includes("contexts")
) {
  const result = spawnSync(
    "pnpm",
    ["--filter", "@skillplane/domain", "exec", "vitest", "run", "src/contexts.test.ts"],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

if (
  filters.length === 1 &&
  filters[0] === "@skillplane/mcp-schema" &&
  positional.some((name) => ["amend", "contexts", "schemas"].includes(name))
) {
  const result = spawnSync(
    "pnpm",
    [
      "--filter",
      "@skillplane/mcp-schema",
      "exec",
      "vitest",
      "run",
      "src/schema.test.ts",
      "src/mutation-schema.test.ts",
    ],
    {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: "inherit",
    },
  );
  process.exit(result.status ?? 1);
}

const result = spawnSync("pnpm", ["exec", "turbo", "run", "test:unit", ...args], {
  cwd: repoRoot,
  encoding: "utf8",
  stdio: "inherit",
});
process.exit(result.status ?? 1);
import { describe, expect, it } from "vitest";
import { classifyApiScope, createRoutedApiApplication } from "./workspace-routing.js";

const objectStorage = {
  head: async () => null,
  get: async () => null,
  put: async () => null,
  delete: async () => undefined,
  list: async () => ({ objects: [] }),
};

describe("API scope classification", () => {
  it("keeps identity, membership, and public projection routes global", () => {
    for (const path of [
      "/auth/session",
      "/api/v1/workspaces/workspace%3Aone/members",
      "/api/v1/skills/public/acme/review",
      "/api/v1/stats/public",
    ]) {
      expect(
        classifyApiScope(new Request(`https://app.skillplane.dev${path}`)),
      ).toEqual({
        kind: "global",
      });
    }
  });

  it("routes workspace and regional resource paths", () => {
    expect(
      classifyApiScope(
        new Request(
          "https://app.skillplane.dev/api/v1/workspaces/workspace%3Aone/skills",
        ),
      ),
    ).toEqual({ kind: "workspace", workspaceId: "workspace:one" });
    expect(
      classifyApiScope(
        new Request("https://app.skillplane.dev/api/v1/skills/skill%3Aone"),
      ),
    ).toEqual({ kind: "resource", resourceType: "skill", resourceId: "skill:one" });
  });

  it("boots a private cell without gateway-only OTP or email bindings", async () => {
    const topology = {
      version: 1,
      mode: "multi-cell",
      public: {
        appAuthority: "http://localhost:5700",
        mcpResource: "http://127.0.0.1:5701/mcp",
      },
      controlPlane: {
        regionId: "global",
        databaseBinding: "CONTROL_DATABASE",
        publicObjectStorageBinding: "PUBLIC_BUNDLES",
        issuer: "http://localhost:5700",
        oauthResource: "http://127.0.0.1:5701/mcp",
      },
      cells: [
        {
          regionId: "in-south",
          databaseBinding: "CELL_DATABASE",
          objectStorageBinding: "CELL_BUNDLES",
          appServiceBinding: "CELL_APP",
          mcpServiceBinding: "CELL_MCP",
          publiclyRoutable: false,
        },
        {
          regionId: "us-east",
          databaseBinding: "OTHER_DATABASE",
          objectStorageBinding: "OTHER_BUNDLES",
          appServiceBinding: "OTHER_APP",
          mcpServiceBinding: "OTHER_MCP",
          publiclyRoutable: false,
        },
      ],
      routing: {
        activeKeyId: "current",
        verificationKeyIds: ["current"],
        assertionAudience: "skillplane-cell",
        assertionTtlSeconds: 20,
      },
    };
    const local = { fetch: async () => new Response("unexpected") };
    const services = async () => {
      throw new Error("global routes must not build regional services");
    };
    const routed = createRoutedApiApplication({ local, services });
    const response = await routed.fetch(new Request("http://localhost:5700/auth"), {
      RUNTIME_ENV: "local",
      DATABASE_ADAPTER: "postgres",
      OAUTH_ISSUER: "http://localhost:5700",
      OAUTH_RESOURCE: "http://127.0.0.1:5701/mcp",
      SKILLPLANE_ROLE: "cell",
      SKILLPLANE_REGION_ID: "in-south",
      SKILLPLANE_TOPOLOGY: JSON.stringify(topology),
      WORKSPACE_ROUTING_KEYS: JSON.stringify({
        current: "routing-secret-independent-from-oauth",
      }),
      CONTROL_DATABASE: "REDACTED",
      CELL_DATABASE: "REDACTED",
      CELL_BUNDLES: objectStorage,
    });

    expect(response.status).toBe(404);
    await expect(response.json()).resolves.toMatchObject({
      error: { code: "REGIONAL_ROUTE_NOT_FOUND" },
    });
  });
});
import { describe, expect, it } from "vitest";
import { classifyMcpScope } from "./workspace-routing.js";

function call(name: string, arguments_: Record<string, unknown> = {}) {
  return new Request("https://mcp.skillplane.dev/mcp", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "tools/call",
      params: { name, arguments: arguments_ },
    }),
  });
}

describe("MCP workspace routing", () => {
  it("keeps protocol and workspace catalog operations global", async () => {
    await expect(classifyMcpScope(call("workspaces_list"))).resolves.toEqual({
      kind: "global",
    });
  });

  it("routes workspace and skill selectors without exposing cell hosts", async () => {
    await expect(
      classifyMcpScope(call("skills_list", { workspace: { slug: "acme" } })),
    ).resolves.toEqual({
      kind: "workspace-slug",
      value: "acme",
      allowPublic: false,
    });
    await expect(
      classifyMcpScope(call("skill_retrieve", { skill: { id: "skill:one" } })),
    ).resolves.toEqual({
      kind: "skill-id",
      value: "skill:one",
      allowPublic: true,
    });
  });

  it("rejects mixed-workspace batches", async () => {
    const request = new Request("https://mcp.skillplane.dev/mcp", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify([
        {
          jsonrpc: "2.0",
          id: 1,
          method: "tools/call",
          params: {
            name: "skills_search",
            arguments: { workspaceId: "workspace:one" },
          },
        },
        {
          jsonrpc: "2.0",
          id: 2,
          method: "tools/call",
          params: {
            name: "skills_search",
            arguments: { workspaceId: "workspace:two" },
          },
        },
      ]),
    });
    await expect(classifyMcpScope(request)).rejects.toMatchObject({
      code: "WORKSPACE_BATCH_INVALID",
    });
  });
});

