    context: DatafnNamespaceMigrationContext,
  ): Promise<void>;
  warmTarget(context: DatafnNamespaceMigrationContext): Promise<void>;
  resumeTarget(context: DatafnNamespaceMigrationContext): Promise<void>;
  rollbackSource(
    context: DatafnNamespaceMigrationContext & { readonly cause: unknown },
  ): Promise<void>;
}

export interface WorkspaceMigrationJournal {
  started(input: {
    readonly id: string;
    readonly workspaceId: string;
    readonly sourceRegionId: string;
    readonly targetRegionId: string;
    readonly sourceEpoch: number;
  }): Promise<void>;
  completed(id: string, proof: WorkspaceMigrationProof): Promise<void>;
  failed(id: string, errorCode: string): Promise<void>;
}

export class PostgresWorkspaceMigrationJournal implements WorkspaceMigrationJournal {
  constructor(private readonly database: PlacementSqlClient) {}

  async started(input: Parameters<WorkspaceMigrationJournal["started"]>[0]) {
    await this.database.query(
      `INSERT INTO workspace_migration_runs
         (id, workspace_id, source_region_id, target_region_id, source_epoch,
          status, phase, recovery_fence, evidence)
       VALUES ($1, $2, $3, $4, $5, 'running', 'fence', $5, '{}'::jsonb)`,
      [
        input.id,
        input.workspaceId,
        input.sourceRegionId,
        input.targetRegionId,
        input.sourceEpoch,
      ],
    );
  }

  async completed(id: string, proof: WorkspaceMigrationProof) {
    await this.database.query(
      `UPDATE workspace_migration_runs
          SET status = 'completed', phase = 'complete', final_epoch = $2,
              evidence = $3::jsonb, completed_at = now(), updated_at = now()
        WHERE id = $1 AND status = 'running'`,
      [id, proof.finalEpoch, JSON.stringify(proof)],
    );
  }

  async failed(id: string, errorCode: string) {
    await this.database.query(
      `UPDATE workspace_migration_runs
          SET status = 'failed', phase = 'rollback',
              evidence = evidence || $2::jsonb,
              completed_at = now(), updated_at = now()
        WHERE id = $1 AND status = 'running'`,
      [id, JSON.stringify({ errorCode, rollbackRequired: true })],
    );
  }
}

/** Composes Skillplane copy/verification hooks with DataFn's fenced move state machine. */
export async function migrateWorkspace(input: {
  readonly directory: WorkspacePlacementDirectory;
  readonly workspaceId: string;
  readonly targetRegionId: string;
  readonly targetDestinationRef?: string;
  readonly operations: WorkspaceMigrationOperations;
  readonly now?: () => number;
  readonly onEvent?: (event: DatafnRoutingEvent) => void | Promise<void>;
}): Promise<{
  readonly placement: WorkspacePlacement;
  readonly proof: WorkspaceMigrationProof;
}> {
  const now = input.now ?? Date.now;
  const before = await input.directory.get(input.workspaceId);
  if (before?.state !== "active") {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  const startedAt = new Date(now()).toISOString();
  const checks: MigrationCheck[] = [];
  const placement = await migrateDatafnNamespace({
    directory: input.directory,
    namespace: input.workspaceId,
    targetRegionId: input.targetRegionId,
    ...(input.targetDestinationRef
      ? { targetDestinationRef: input.targetDestinationRef }
      : {}),
    hooks: {
      quiesceSource: (context) => input.operations.quiesceSource(context),
      drainPermissionDirectory: (context) => input.operations.drainOutboxes(context),
      async copyTenantData(context) {
        await input.operations.copyDatabase(context);
        await input.operations.copyBundles(context);
      },
      async validateTenantData(context) {
        checks.push(...(await input.operations.verifyDatabase(context)));
        checks.push(...(await input.operations.verifyBundles(context)));
        if (checks.length === 0 || checks.some((check) => !check.matched)) {
          throw new Error("WORKSPACE_MIGRATION_VERIFICATION_FAILED");
        }
      },
      rebuildPermissionDirectory: (context) =>
        input.operations.rebuildGlobalResourceDirectory(context),
      warmTarget: (context) => input.operations.warmTarget(context),
      resumeTarget: (context) => input.operations.resumeTarget(context),
      rollbackSource: (context) => input.operations.rollbackSource(context),
    },
    now,
    onEvent:
      input.onEvent ??
      ((event) => {
        logWorkspaceRoutingEvent("migration", event);
      }),
  });
  return {
    placement,
    proof: {
      workspaceId: input.workspaceId,
      sourceRegionId: before.regionId,
      targetRegionId: input.targetRegionId,
      sourceEpoch: before.epoch,
      finalEpoch: placement.epoch,
      startedAt,
      completedAt: new Date(now()).toISOString(),
      checks,
      rollbackTested: false,
    },
  };
}

/** Runs the fenced move while persisting operator-visible evidence. */
export async function migrateWorkspaceWithJournal(
  input: Parameters<typeof migrateWorkspace>[0] & {
    readonly journal: WorkspaceMigrationJournal;
    readonly migrationId?: string;
  },
): Promise<{
  readonly migrationId: string;
  readonly placement: WorkspacePlacement;
  readonly proof: WorkspaceMigrationProof;
}> {
  const source = await input.directory.get(input.workspaceId);
  if (source?.state !== "active") {
    throw new Error("WORKSPACE_MIGRATION_SOURCE_NOT_ACTIVE");
  }
  const migrationId = input.migrationId ?? `workspace-migration:${crypto.randomUUID()}`;
  await input.journal.started({
    id: migrationId,
    workspaceId: input.workspaceId,
    sourceRegionId: source.regionId,
    targetRegionId: input.targetRegionId,
    sourceEpoch: source.epoch,
  });
  try {
    const result = await migrateWorkspace(input);
    await input.journal.completed(migrationId, result.proof);
    return { migrationId, ...result };
  } catch (error) {
    const code =
      error instanceof Error && /^[A-Z0-9_:-]{1,160}$/u.test(error.message)
        ? error.message
        : "WORKSPACE_MIGRATION_FAILED";
    await input.journal.failed(migrationId, code).catch(() => undefined);
    throw error;
  }
}
export function globalPublishedBundleKey(input: {
  readonly workspaceId: string;
  readonly skillId: string;
  readonly versionId: string;
  readonly digest: `sha256:${string}`;
}): string {
  const safe = (value: string, label: string): string => {
    if (!/^[A-Za-z0-9:_-]{1,180}$/u.test(value)) {
      throw new Error(`PUBLICATION_${label.toUpperCase()}_INVALID`);
    }
    return value;
  };
  const digest = input.digest.slice("sha256:".length);
  if (!/^[a-f0-9]{64}$/u.test(digest)) {
    throw new Error("PUBLICATION_DIGEST_INVALID");
  }
  return [
    "public",
    "workspaces",
    safe(input.workspaceId, "workspace"),
    "skills",
    safe(input.skillId, "skill"),
    "versions",
    safe(input.versionId, "version"),
    "sha256",
    `${digest}.zip`,
  ].join("/");
}

export interface ImmutablePublicationStore {
  putIfAbsent(input: {
    readonly key: string;
    readonly bytes: Uint8Array;
    readonly digest: `sha256:${string}`;
    readonly metadata: Readonly<Record<string, string>>;
  }): Promise<"created" | "exists">;
  read(input: {
    readonly key: string;
    readonly digest: `sha256:${string}`;
  }): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

export interface ImmutableObjectBucket {
  head(key: string): Promise<unknown>;
  get(key: string): Promise<{ arrayBuffer(): Promise<ArrayBuffer> } | null>;
  put(
    key: string,
    bytes: Uint8Array,
    options: {
      readonly onlyIf: { readonly etagDoesNotMatch: string };
      readonly httpMetadata: { readonly contentType: string };
      readonly customMetadata: Readonly<Record<string, string>>;
    },
  ): Promise<unknown>;
  delete(key: string): Promise<void>;
}

/** Adapts a private R2-compatible bucket to the immutable projection contract. */
export function createImmutableObjectPublicationStore(
  bucket: ImmutableObjectBucket,
): ImmutablePublicationStore {
  return {
    async putIfAbsent(input) {
      if (await bucket.head(input.key)) return "exists";
      const created = await bucket.put(input.key, input.bytes, {
        onlyIf: { etagDoesNotMatch: "*" },
        httpMetadata: { contentType: "application/zip" },
        customMetadata: { ...input.metadata, digest: input.digest },
      });
      return created ? "created" : "exists";
    },
    async read(input) {
      const object = await bucket.get(input.key);
      if (!object) throw new Error("PUBLICATION_OBJECT_NOT_FOUND");
      return new Uint8Array(await object.arrayBuffer());
    },
    delete: (key) => bucket.delete(key),
  };
}

export interface PublicProjectionDirectory {
  publish(input: {
    readonly workspaceId: string;
    readonly workspaceSlug: string;
    readonly skillId: string;
    readonly skillSlug: string;
    readonly versionId: string;
    readonly semanticVersion: string;
    readonly digest: `sha256:${string}`;
    readonly objectKey: string;
    readonly document?: Readonly<Record<string, unknown>>;
    readonly searchText?: string;
  }): Promise<void>;
  unpublish(input: {
    readonly workspaceId: string;
    readonly skillId: string;
    readonly versionId: string;
  }): Promise<void>;
}

interface ProjectionSqlClient {
  query(text: string, values?: readonly unknown[]): Promise<unknown>;
}

/** Durable global metadata projection; object visibility is updated only after digest verification. */
export class PostgresPublicProjectionDirectory implements PublicProjectionDirectory {
  constructor(private readonly database: ProjectionSqlClient) {}

  async publish(input: Parameters<PublicProjectionDirectory["publish"]>[0]) {
    await this.database.query(
      `INSERT INTO public_skill_projections
         (workspace_id, workspace_slug, skill_id, skill_slug, version_id,
          semantic_version, digest, object_key, document, search_text, state,
          published_at, unpublished_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb, $10,
               'published', now(), NULL, now())
       ON CONFLICT (workspace_id, skill_id, version_id)
       DO UPDATE SET workspace_slug = EXCLUDED.workspace_slug,
                     skill_slug = EXCLUDED.skill_slug,
                     semantic_version = EXCLUDED.semantic_version,
                     digest = EXCLUDED.digest,
                     object_key = EXCLUDED.object_key,
                     document = EXCLUDED.document,
                     search_text = EXCLUDED.search_text,
                     state = 'published', unpublished_at = NULL,
                     updated_at = now()`,
      [
        input.workspaceId,
        input.workspaceSlug,
        input.skillId,
        input.skillSlug,
        input.versionId,
        input.semanticVersion,
        input.digest,
        input.objectKey,
        JSON.stringify(input.document ?? {}),
        input.searchText ?? "",
      ],
    );
  }

  async unpublish(input: Parameters<PublicProjectionDirectory["unpublish"]>[0]) {
    await this.database.query(
      `UPDATE public_skill_projections
          SET state = 'unpublished', unpublished_at = now(), updated_at = now()
        WHERE workspace_id = $1 AND skill_id = $2
          AND state = 'published'`,
      [input.workspaceId, input.skillId],
    );
  }
}

async function sha256(bytes: Uint8Array): Promise<`sha256:${string}`> {
  const copy = new Uint8Array(bytes.byteLength);
  copy.set(bytes);
  const digest = await crypto.subtle.digest("SHA-256", copy.buffer);
  return `sha256:${[...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("")}`;
}

/** Copies an immutable regional bundle before atomically exposing its global projection. */
export async function publishGlobalProjection(input: {
  readonly source: ImmutablePublicationStore;
  readonly destination: ImmutablePublicationStore;
  readonly directory: PublicProjectionDirectory;
  readonly sourceKey: string;
  readonly workspaceId: string;
  readonly workspaceSlug: string;
  readonly skillId: string;
  readonly skillSlug: string;
  readonly versionId: string;
  readonly semanticVersion: string;
  readonly digest: `sha256:${string}`;
  readonly document?: Readonly<Record<string, unknown>>;
  readonly searchText?: string;
}): Promise<string> {
  const bytes = await input.source.read({ key: input.sourceKey, digest: input.digest });
  if ((await sha256(bytes)) !== input.digest) {
    throw new Error("PUBLICATION_SOURCE_DIGEST_MISMATCH");
  }
  const objectKey = globalPublishedBundleKey(input);
  await input.destination.putIfAbsent({
    key: objectKey,
    bytes,
    digest: input.digest,
    metadata: {
      workspaceId: input.workspaceId,
      skillId: input.skillId,
      versionId: input.versionId,
      digest: input.digest,
    },
  });
  const verified = await input.destination.read({
    key: objectKey,
    digest: input.digest,
  });
  if ((await sha256(verified)) !== input.digest) {
    throw new Error("PUBLICATION_DESTINATION_DIGEST_MISMATCH");
  }
  await input.directory.publish({
    workspaceId: input.workspaceId,
    workspaceSlug: input.workspaceSlug,
    skillId: input.skillId,
    skillSlug: input.skillSlug,
    versionId: input.versionId,
    semanticVersion: input.semanticVersion,
    digest: input.digest,
    objectKey,
    ...(input.document ? { document: input.document } : {}),
    ...(input.searchText !== undefined ? { searchText: input.searchText } : {}),
  });
  return objectKey;
}
import { z } from "zod";

export const PRODUCTION_APP_AUTHORITY = "https://app.skillplane.dev";
export const PRODUCTION_MCP_RESOURCE = "https://mcp.skillplane.dev/mcp";

const identifier = z
  .string()
  .min(1)
  .max(80)
  .regex(/^[a-z][a-z0-9-]*$/u);
const bindingName = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[A-Z][A-Z0-9_]*$/u);
function secureOrLoopback(parsed: URL): boolean {
  return (
    parsed.protocol === "https:" ||
    (parsed.protocol === "http:" &&
      ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname))
  );
}

const authority = z.url().refine((value) => {
  const parsed = new URL(value);
  return (
    secureOrLoopback(parsed) &&
    !parsed.username &&
    !parsed.password &&
    !parsed.search &&
    !parsed.hash &&
    parsed.pathname === "/"
  );
}, "must be a secure or loopback origin without credentials, path, query, or fragment");
const mcpResource = z.url().refine((value) => {
  const parsed = new URL(value);
  return (
    secureOrLoopback(parsed) &&
    !parsed.username &&
    !parsed.password &&
    !parsed.search &&
    !parsed.hash &&
    parsed.pathname === "/mcp"
  );
}, "must be a secure or loopback /mcp resource URL");

const cellSchema = z
  .object({
    regionId: identifier,
    databaseBinding: bindingName,
    objectStorageBinding: bindingName,
    appServiceBinding: bindingName,
    mcpServiceBinding: bindingName,
    publiclyRoutable: z.literal(false),
  })
  .strict();

const topologySchema = z
  .object({
    version: z.literal(1),
    mode: z.enum(["single-cell", "multi-cell"]),
    public: z
      .object({
        appAuthority: authority,
        mcpResource,
      })
      .strict(),
    controlPlane: z
      .object({
        regionId: identifier,
        databaseBinding: bindingName,
        publicObjectStorageBinding: bindingName,
        issuer: authority,
        oauthResource: mcpResource,
      })
      .strict(),
    cells: z.array(cellSchema).min(1),
    routing: z
      .object({
        activeKeyId: identifier,
        verificationKeyIds: z.array(identifier).min(1),
        assertionAudience: identifier,
        assertionTtlSeconds: z.number().int().min(1).max(60),
      })
      .strict(),
  })
  .strict();

export type SkillplaneTopologyManifest = z.infer<typeof topologySchema>;
export type RegionalCellManifest = SkillplaneTopologyManifest["cells"][number];

export type TopologyErrorCode =
  | "TOPOLOGY_INVALID"
  | "TOPOLOGY_DUPLICATE_REGION"
  | "TOPOLOGY_DUPLICATE_BINDING"
  | "TOPOLOGY_REGION_COUNT_INVALID"
  | "TOPOLOGY_ISSUER_DRIFT"
  | "TOPOLOGY_KEY_ROTATION_INVALID";

export class TopologyError extends Error {
  readonly code: TopologyErrorCode;
  readonly fields: readonly string[];

  constructor(code: TopologyErrorCode, message: string, fields: readonly string[]) {
    super(message);
    this.name = "TopologyError";
    this.code = code;
    this.fields = fields;
  }
}

function duplicates(values: readonly string[]): string[] {
  const seen = new Set<string>();
  const found = new Set<string>();
  for (const value of values) {
    if (seen.has(value)) found.add(value);
    seen.add(value);
  }
  return [...found].sort();
}

export function parseTopologyManifest(
  input: unknown,
  options: { readonly production?: boolean } = {},
): SkillplaneTopologyManifest {
  let raw: unknown = input;
  if (typeof input === "string") {
    try {
      raw = JSON.parse(input);
    } catch {
      throw new TopologyError(
        "TOPOLOGY_INVALID",
        "The topology manifest is not valid JSON",
        ["SKILLPLANE_TOPOLOGY"],
      );
    }
  }
  const parsed = topologySchema.safeParse(raw);
  if (!parsed.success) {
    throw new TopologyError(
      "TOPOLOGY_INVALID",
      "The topology manifest violates its schema",
      parsed.error.issues.map((issue) => issue.path.join(".") || "manifest"),
    );
  }
  const manifest = parsed.data;
  const duplicateRegions = duplicates(manifest.cells.map((cell) => cell.regionId));
  if (
    duplicateRegions.length > 0 ||
    manifest.cells.some((cell) => cell.regionId === manifest.controlPlane.regionId)
  ) {
    throw new TopologyError(
      "TOPOLOGY_DUPLICATE_REGION",
      "Control-plane and regional cell IDs must be unique",
      ["controlPlane.regionId", "cells.regionId"],
    );
  }
  if (
    (manifest.mode === "multi-cell" && manifest.cells.length < 2) ||
    (manifest.mode === "single-cell" && manifest.cells.length !== 1)
  ) {
    throw new TopologyError(
      "TOPOLOGY_REGION_COUNT_INVALID",
      "The topology mode does not match its regional cell count",
      ["mode", "cells"],
    );
  }
  const allBindings = [
    manifest.controlPlane.databaseBinding,
    manifest.controlPlane.publicObjectStorageBinding,
    ...manifest.cells.flatMap((cell) => [
      cell.databaseBinding,
      cell.objectStorageBinding,
      cell.appServiceBinding,
      cell.mcpServiceBinding,
    ]),
  ];
  if (duplicates(allBindings).length > 0) {
    throw new TopologyError(
      "TOPOLOGY_DUPLICATE_BINDING",
      "Every database, storage, and service binding must have one owner",
      ["controlPlane", "cells"],
    );
  }
  if (
    manifest.public.appAuthority !== manifest.controlPlane.issuer ||
    manifest.public.mcpResource !== manifest.controlPlane.oauthResource ||
    (options.production &&
      (manifest.public.appAuthority !== PRODUCTION_APP_AUTHORITY ||
        manifest.public.mcpResource !== PRODUCTION_MCP_RESOURCE))
  ) {
    throw new TopologyError(
      "TOPOLOGY_ISSUER_DRIFT",
      "Public authorities and the control-plane OAuth identity must be canonical",
      ["public", "controlPlane.issuer", "controlPlane.oauthResource"],
    );
  }
  const keyIds = new Set(manifest.routing.verificationKeyIds);
  if (!keyIds.has(manifest.routing.activeKeyId) || keyIds.size > 3) {
    throw new TopologyError(
      "TOPOLOGY_KEY_ROTATION_INVALID",
      "The active routing key must be in the bounded verification keyring",
      ["routing.activeKeyId", "routing.verificationKeyIds"],
    );
  }
  return manifest;
}

export function createSingleCellTopology(input: {
  readonly appAuthority: string;
  readonly mcpResource: string;
  readonly controlDatabaseBinding?: string;
  readonly publicObjectStorageBinding?: string;
  readonly regionId?: string;
  readonly regionalDatabaseBinding?: string;
  readonly regionalObjectStorageBinding?: string;
}): SkillplaneTopologyManifest {
  return parseTopologyManifest({
    version: 1,
    mode: "single-cell",
    public: {
      appAuthority: input.appAuthority,
      mcpResource: input.mcpResource,
    },
    controlPlane: {
      regionId: "global",
      databaseBinding: input.controlDatabaseBinding ?? "CONTROL_HYPERDRIVE",
      publicObjectStorageBinding:
        input.publicObjectStorageBinding ?? "PUBLIC_SKILL_BUNDLES",
      issuer: input.appAuthority,
      oauthResource: input.mcpResource,
    },
    cells: [
      {
        regionId: input.regionId ?? "local",
        databaseBinding: input.regionalDatabaseBinding ?? "CELL_HYPERDRIVE",
        objectStorageBinding:
          input.regionalObjectStorageBinding ?? "CELL_SKILL_BUNDLES",
        appServiceBinding: "CELL_APP",
        mcpServiceBinding: "CELL_MCP",
        publiclyRoutable: false,
      },
    ],
    routing: {
      activeKeyId: "current",
      verificationKeyIds: ["current"],
      assertionAudience: "skillplane-cell",
      assertionTtlSeconds: 20,
    },
  });
}

