 40	interface ProjectionOutboxRow extends Record<string, unknown> {
 41	  readonly id: string;
 42	  readonly workspace_id: string;
 43	  readonly event_type: RegionalProjectionEvent["eventType"];
 44	  readonly payload: unknown;
 45	  readonly fencing_epoch: number;
