 48	interface ProjectionOutboxSqlClient {
 49	  query(
 50	    text: string,
 51	    values?: readonly unknown[],
 52	  ): Promise<{
 53	    readonly rows: readonly Record<string, unknown>[];
 54	    readonly rowCount?: number | null;
 55	  }>;
