    63	  if (bump === "major") {
    64	    major += 1;
    65	    minor = 0;
    66	    patch = 0;
    67	  } else if (bump === "minor") {
    68	    minor += 1;
    69	    patch = 0;
    70	  } else {
    71	    patch += 1;
    72	  }
    73	  return `${String(major)}.${String(minor)}.${String(patch)}`;
