    44	export function nextSemanticVersion(current: string, bump: SemanticBump): string {
    45	  const match = /^(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/.exec(current);
    46	  if (!match) {
    47	    throw new DomainError(
    48	      "SKILL_PUBLISH_CONFLICT",
    49	      "The current semantic version cannot be advanced",
    50	      409,
    51	    );
    52	  }
    53	  let major = Number(match[1]);
    54	  let minor = Number(match[2]);
    55	  let patch = Number(match[3]);
    56	  if (![major, minor, patch].every(Number.isSafeInteger)) {
    57	    throw new DomainError(
    58	      "SKILL_PUBLISH_CONFLICT",
    59	      "The current semantic version cannot be advanced",
    60	      409,
    61	    );
    62	  }
    63	  if (bump === "major") {
    64	    major += 1;
    65	    minor = 0;
    66	    patch = 0;
    67	  } else if (bump === "minor") {
    68	    minor += 1;
    69	    patch = 0;
    70	  } else {
    71	    patch += 1;
    72	  }
    73	  return `${String(major)}.${String(minor)}.${String(patch)}`;
    74	}
