     1	import {
     2	  DomainError,
     3	  parseSkillArchiveFilter,
     4	  parseSkillVisibility,
     5	} from "@skillplane/domain";
     6	import type { Hono } from "hono";
     7	import type { ApiEnvironment } from "../context.js";
     8	import { success } from "../envelopes.js";
     9	
    10	function parseLimit(value: string | undefined): number | undefined {
    11	  if (value === undefined) return undefined;
    12	  const parsed = Number(value);
    13	  if (!Number.isSafeInteger(parsed) || parsed < 1 || parsed > 100) {
    14	    throw new DomainError(
    15	      "VALIDATION_FAILED",
    16	      "limit must be an integer between 1 and 100",
    17	      400,
    18	      { field: "limit" },
    19	    );
    20	  }
    21	  return parsed;
    22	}
    23	
    24	export function registerSkillSearchRoutes(app: Hono<ApiEnvironment>): void {
    25	  app.get("/api/v1/skills/search", async (context) => {
    26	    const services = context.get("services");
    27	    if (!services) {
    28	      throw new DomainError(
    29	        "AUTHENTICATION_REQUIRED",
    30	        "Skill search is unavailable",
    31	        503,
    32	      );
    33	    }
    34	    const repeatedTags = context.req.queries("tag") ?? [];
    35	    const commaTags =
    36	      context.req
    37	        .query("tags")
    38	        ?.split(",")
    39	        .map((tag) => tag.trim())
    40	        .filter(Boolean) ?? [];
    41	    const limit = parseLimit(context.req.query("limit"));
    42	    const visibility = [
    43	      ...(context.req.queries("visibility") ?? []),
    44	      ...(context.req
    45	        .query("visibilities")
    46	        ?.split(",")
    47	        .map((value) => value.trim())
    48	        .filter(Boolean) ?? []),
    49	    ].map(parseSkillVisibility);
    50	    if (services.publicProjectionService && !context.req.query("workspaceId")) {
    51	      const page = await services.publicProjectionService.discover({
    52	        query: context.req.query("q") ?? "",
    53	        tags: [...repeatedTags, ...commaTags],
    54	        ...(limit !== undefined ? { limit } : {}),
    55	        cursor: context.req.query("cursor") ?? null,
    56	      });
    57	      context.header("Cache-Control", "private, no-store");
    58	      return context.json(success(context, page));
    59	    }
    60	    const page = await services.skillSearchService.search({
    61	      query: context.req.query("q") ?? "",
    62	      tags: [...repeatedTags, ...commaTags],
    63	      visibility,
    64	      archive: parseSkillArchiveFilter(context.req.query("state") ?? "active"),
    65	      ...(limit !== undefined ? { limit } : {}),
    66	      cursor: context.req.query("cursor") ?? null,
    67	      principal: context.get("principal"),
    68	    });
    69	    context.header("Cache-Control", "private, no-store");
    70	    return context.json(success(context, page));
    71	  });
    72	}
