 30	const regionalAdapterSchema = { ...regionalWorkspaceSchema };
 31	
 32	export type DatabaseRole = "combined" | "control" | "regional";
 33	
 34	export type SkillplaneDatabase = NodePgDatabase<typeof adapterSchema>;
 35	
 36	export interface DatabaseClient {
 37	  readonly role: DatabaseRole;
 38	  readonly pool: Pool;
 39	  readonly db: SkillplaneDatabase;
 40	  readonly adapter: Adapter;
 41	  close(): Promise<void>;
 42	}
 43	
 44	export interface DatabaseClientOptions {
 45	  readonly connectionString: string;
 46	  readonly applicationName?: string;
 47	  readonly maxConnections?: number;
 48	  readonly ssl?: PoolConfig["ssl"];
 49	  readonly role?: DatabaseRole;
 50	}
 51	
 52	export function createDatabaseClient(options: DatabaseClientOptions): DatabaseClient {
 53	  const role = options.role ?? "combined";
 54	  const pool = new Pool({
 55	    connectionString: options.connectionString,
 56	    application_name: options.applicationName ?? "skillplane",
 57	    max: options.maxConnections ?? 10,
 58	    idleTimeoutMillis: 30_000,
 59	    connectionTimeoutMillis: 10_000,
 60	    keepAlive: true,
 61	    ssl: options.ssl,
 62	  });
 63	  const selectedSchema =
 64	    role === "control"
 65	      ? controlAdapterSchema
 66	      : role === "regional"
 67	        ? regionalAdapterSchema
 68	        : adapterSchema;
 69	  // Consumers use the pool for domain SQL and the adapter for AuthFn/DataFn.
 70	  // The declared superset type preserves compatibility while the runtime
 71	  // adapter is deliberately restricted to its database owner's tables.
 72	  const db = drizzle(pool, { schema: selectedSchema }) as SkillplaneDatabase;
 73	  const adapter = drizzleAdapter({
 74	    db,
 75	    dialect: "postgres",
 76	  });
 77	  return {
 78	    role,
 79	    pool,
 80	    db,
 81	    adapter,
 82	    close: () => pool.end(),
 83	  };
 84	}
 85	
 86	export function createRuntimeDatabaseClient(config: RuntimeConfig): DatabaseClient {
 87	  return createDatabaseClient({
 88	    connectionString: config.database.connectionString,
 89	    applicationName: `skillplane-${config.environment}`,
 90	    maxConnections: config.database.source === "hyperdrive" ? 5 : 10,
 91	  });
 92	}
 93	
 94	export function createControlDatabaseClient(
 95	  options: Omit<DatabaseClientOptions, "role">,
 96	): DatabaseClient {
 97	  return createDatabaseClient({ ...options, role: "control" });
 98	}
 99	
100	export function createRegionalDatabaseClient(
101	  options: Omit<DatabaseClientOptions, "role">,
102	): DatabaseClient {
103	  return createDatabaseClient({ ...options, role: "regional" });
104	}
