     1	import { createHash } from "node:crypto";
     2	import { readdir, readFile } from "node:fs/promises";
     3	import { Pool, type PoolClient } from "pg";
     4	import { packageRoot } from "./database-url.js";
     5	
     6	import { resolve } from "node:path";
     7	
     8	const migrationsDirectory = resolve(packageRoot, "migrations");
     9	const migrationPattern = /^\d{4}_[a-z0-9_]+\.sql$/;
    10	
    11	export interface Migration {
    12	  readonly id: string;
    13	  readonly sha256: string;
    14	  readonly sql: string;
    15	}
    16	
    17	export interface MigrationResult {
    18	  readonly applied: readonly string[];
    19	  readonly alreadyApplied: readonly string[];
    20	}
    21	
    22	export async function loadMigrations(
    23	  directory = migrationsDirectory,
    24	): Promise<readonly Migration[]> {
    25	  const names = (await readdir(directory))
    26	    .filter((name) => migrationPattern.test(name))
    27	    .sort();
    28	  if (names.length === 0) {
    29	    throw new Error(`No migrations found in ${directory}`);
    30	  }
    31	  return Promise.all(
    32	    names.map(async (id) => {
    33	      const sql = await readFile(resolve(directory, id), "utf8");
    34	      return {
    35	        id,
    36	        sha256: createHash("sha256").update(sql).digest("hex"),
    37	        sql,
    38	      };
    39	    }),
    40	  );
    41	}
    42	
    43	async function ensureLedger(client: PoolClient): Promise<void> {
    44	  await client.query(`
    45	    CREATE TABLE IF NOT EXISTS skillplane_schema_migrations (
    46	      id text PRIMARY KEY,
    47	      sha256 text NOT NULL,
    48	      applied_at timestamptz NOT NULL DEFAULT now(),
    49	      execution_ms integer NOT NULL CHECK (execution_ms >= 0)
    50	    )
    51	  `);
    52	}
    53	
    54	export async function migrateDatabase(databaseUrl: string): Promise<MigrationResult> {
    55	  const migrations = await loadMigrations();
    56	  const pool = new Pool({
    57	    connectionString: databaseUrl,
    58	    application_name: "skillplane-migrator",
    59	    max: 1,
    60	  });
    61	  const client = await pool.connect();
    62	  const applied: string[] = [];
    63	  const alreadyApplied: string[] = [];
    64	  try {
    65	    await client.query("SELECT pg_advisory_lock(hashtext($1))", [
    66	      "skillplane-schema-migrations-v1",
    67	    ]);
    68	    await ensureLedger(client);
    69	    const ledger = await client.query<{ id: string; sha256: string }>(
    70	      "SELECT id, sha256 FROM skillplane_schema_migrations ORDER BY id",
    71	    );
    72	    const known = new Map(ledger.rows.map((row) => [row.id, row.sha256]));
    73	
    74	    for (const migration of migrations) {
    75	      const previousHash = known.get(migration.id);
    76	      if (previousHash !== undefined) {
    77	        if (previousHash !== migration.sha256) {
    78	          throw new Error(
    79	            `Applied migration ${migration.id} no longer matches its recorded hash`,
    80	          );
    81	        }
    82	        alreadyApplied.push(migration.id);
    83	        continue;
    84	      }
    85	      const startedAt = performance.now();
    86	      await client.query("BEGIN");
    87	      try {
    88	        await client.query(migration.sql);
    89	        await client.query(
    90	          `INSERT INTO skillplane_schema_migrations
    91	             (id, sha256, execution_ms)
    92	           VALUES ($1, $2, $3)`,
    93	          [
    94	            migration.id,
    95	            migration.sha256,
    96	            Math.max(0, Math.round(performance.now() - startedAt)),
    97	          ],
    98	        );
    99	        await client.query("COMMIT");
   100	        applied.push(migration.id);
   101	      } catch (error) {
   102	        await client.query("ROLLBACK");
   103	        throw error;
   104	      }
   105	    }
   106	    return { applied, alreadyApplied };
   107	  } finally {
   108	    await client
   109	      .query("SELECT pg_advisory_unlock(hashtext($1))", [
   110	        "skillplane-schema-migrations-v1",
   111	      ])
   112	      .catch(() => undefined);
   113	    client.release();
   114	    await pool.end();
   115	  }
   116	}
